local _, WFJ = ...
WFJ.Data.add("quest", {
  [97000] = { "記憶の粒", "Hyjalの破壊されたAllianceの野営地で、Abigail Sawyerの父Lawrenceの手がかりを探す。", "この……第二の生を受ける前、私は父の工房で木目を学びました。\n\n戦がHyjalに及んだとき、父はあとに残り、頂へ向かう者たちのために武器を作りました。私はLordaeronへ逃れました。父の最後の手紙はあの山の野営地から届き、それきり便りはありませんでした。\n\n私の死も、父の死より穏やかなものではなかったでしょう。Undercityで目覚めたとき、何年も経ったように感じましたが、実際にはかろうじて2年でした。\n\nあなたなら登りもこなせそうです。父、Lawrence Sawyerの名残を何か見つけてくだされば、私の慰めになるでしょう。", nil, nil, 0x1f5695c6, 0x2c24c8e7, 0x2c6481dc, nil, nil, "...mm" },
  [97001] = { "Sawyerの遺産", "Sawyer Family LedgerをUndercityのWar QuarterにいるAbigail Sawyerのもとへ持っていく。", "衣装棚の中には、干し草、材木、荷役用の家畜、土地の取引を記録した帳簿がある。そのページの間には、個人的な書きかけのメモも挟まっている。\n\n数字そのものが物語っている。Sawyer家は、材木を武器、道具、家具、荷馬車へと変える腕に長けていた。\n\nページをめくると、一族の他の身内も分かる。親族の中にAbigail Sawyerの名がある。\n\n彼女はこれに大いに興味を持つだろう。", nil, nil, 0x4051d83c, 0x5d0d13e9, 0xdd4e1535, nil, nil, "...mm" },
  [97003] = { "Chol'aruk the Ravener", "Chol'arukの首をBarrensのGur'akに届けてください。", "そこのお前、{class}。手を貸してほしい。ここから北東のThorn Hillの洞窟の奥深くに、獣がねぐらを構えているという噂がある。RazormaneはそいつをChol'aruk、あるいは「The Ravener」と呼んでいる。普通のquilboarの5倍の大きさで、決して満たされることのない血への渇きを持っているそうだ。\n\nほとんどの者はその話を信じていない。だが俺は信じる……以前、同じような奴と戦ったことがあるからだ。\n\nねぐらを探し出し、Chol'arukを殺せ。その首を持ってこい。だが言っておく……しっかり備え、ひとりでは行くな。\n\n血と雷を、{class}。", "こいつらを1体倒すのに、腕の立つ戦士6人の力が必要だった。それでも仕留めるまでに、我々のうち4人が倒されたのだ。\n\nもしこの怪物どもがもっと数多く現れたら、quilboarがこの地にもたらす被害は壊滅的なものになりかねん。", "見事だ、{class}。この忌まわしい化け物どもが実在するという凄惨な証拠を持ってOrgrimmarへ戻れば、誰も俺の話を疑いはしないだろう。だが安心しろ、この栄光はお前のものだ。お前の功績は大声で語ってやる。\n\nLok-tar！", 0xc67797d5, 0xf7cb3419, 0x73b1b3d7, 0x6c001dd2, 0x8617a389, "....." },
  [97005] = { "Chol'aruk the Ravener", "Chol'aruk's HeadをBarrensのBainhamに届けてください。", "ここから北西、Thorn Hillと呼ばれる高台の洞窟を巣にしている、巨大なabominationの噂がある。RazormaneどもはそいつをChol'aruk、あるいは「The Ravener」と呼んでいて、見た者が言うには、オークを丸呑みできるほどでかいそうだ。\n\nそんな話を信じる者は少ないが、俺は信じる……似たような奴と、俺自身が戦ったことがあるからな。こいつらに奪われた者たちの名誉にかけて、この獣は死なねばならない。\n\n強い仲間を集めて、Chol'arukの巣を見つけ出せ。abominationを倒し、その首を持ってこい。", nil, nil, 0xc67797d5, 0x5efacf98, 0xef594ded, nil, nil, "...mm" },
  [97006] = { "公証された権利", "Sawyer Family LedgerをUndercityのTrade QuarterにいるRoyal Overseer Bauhausのもとへ持っていく。", "元のページの私の名前の横に、メモと署名を書き添えておきました。\n\nこれをUndercity CensusのRoyal Overseer Bauhausのところへ持っていき、どこで見つかったのか説明してください。私が店にいたままで、どうしてこれが私の手に渡ったのか、彼は知っておかなければなりません。\n\n正直に、Abigail Sawyerがまた見知らぬ人に身の上話を聞かせ、たまたまあなたにそれを追う手立てがあったのだと言ってかまいません。\n\n改めて、私の家族のためにありがとうございます。", nil, nil, 0x34053bae, 0x2ca290c2, 0xa9f3b860, nil, nil, "...mm" },
  [97007] = { "木材の残骸", "公証済みのSawyer Family LedgerをWar QuarterのAbigail Sawyerのもとへ届ける。", "Abigailの記録に関わるページに判を押し、こちらの書類も更新しておいた。\n\n財産のいずれかをForsakenの領地へ移すつもりなら、AbigailはRoyal Censusに追って届け出を送らねばならない。\n\n彼女の帳簿を返してよい。その際、これを伝えておけ。War Quarterの補給部への契約上の義務はまだ果たされていない。よって、これら戦前の所有権の主張に基づいて動く前に、待つのが賢明だろう。", nil, nil, 0x73fe4ab0, 0xb7768aa0, 0x26410a41, nil, nil, "...mm" },
  [97009] = { "Maerionの苦難", "Felhound Spikesを$N1個、Dae'gunのMaerion Thaelemachesのもとへ持っていく。", "血を流したまま見捨てられた……軍が逃げられるよう、脇へ投げ捨てられたのだ。俺は奴らのために時間を稼いで死ぬはずだった。\n\nだが代わりに、生き永らえる呪いをかけられ、鋼が成し得なかったことを、燃え続ける悪魔どもが成し遂げるのを見せつけられてきた。これが俺の運命だ。\n\nだが何かが変わりつつある。HordeとAllianceがこの穢された山へ戻り、戦が再びうごめいている。\n\n俺の怒りがそれに応える。\n\nお前の怒りもそうなら、証明してみせろ。このDefiling Houndsからfelhound spikesを2つかみ分持ってこい。\n\nその痛みが、我らの意志をひとつにする。", nil, nil, 0xca90f5f4, 0xb7886262, 0x9f7d6d50, nil, nil, "...mm" },
  [97010] = { "盲目の復讐", "Horde Mage Towerの頂上に登り、Explosive Runeshardを投げて、悪魔たちへの攻撃を始めるようMaerion Thaelemachesに合図する。", "ルーンを刻んだ欠片の準備はできた。十分な高さから落とせば、衝撃で砕け散り、鎧も悪魔の肉も引き裂く。\n\nこの荒れ地を見下ろす塔がある。必要な高さはそこで得られる。\n\n登るぞ。俺は影に身を潜め、お前の脇を守る。\n\n頂上に着いたら、最初の一投で俺に合図しろ。奴らに破滅を降らせてやる。", nil, nil, 0x9f315c13, 0x4c3b6399, 0x24a6be48, nil, nil, "...mm" },
  [97017] = { "初めての騎乗用の雄羊", "騎乗用の雄羊を見て回り、最初の乗騎を選ぶ。", "おお、今日はお前さんにとって大事な日のようだな。初めての雄羊を求めて来たんだろ？\n\nこの雄羊たちはAzeroth中で一番揺るがず頑丈なやつらだ。乗り手を猛然と守ってくれる。ああ、旅の相棒として、これ以上頼もしいやつはなかなか見つからんぞ。\n\nさて、お前さんは大事な選択をせにゃならん。お前さんと雄羊は一緒に世界を巡るんだから、よく考えて選ぶんだぞ！心配すんな、若いの。どれを選んでも、それが正しい選択になるさ。\n\n雄羊たちを見てきて、選び終わったらわしのところへ戻ってこい。", nil, nil, 0x7f649662, 0xc7e22043, 0x98dc8147, nil, nil, "...mm" },
  [97018] = { "騎乗を学ぶ", "Ultham IronhornからApprentice Ridingのスキルを習得する。", "やあ、{class}！どうやらお前さんも、わしが雄羊の乗り方を教えてやれるくらい、冒険者として経験を積んだようだな。もちろん、料金はもらうがね。\n\nわしのところで訓練を受けたら、Veronが乗騎をただでくれる。その後は、欲しい乗騎を好きなだけ買えるようになるぞ。世の中にはいろんな生き物がいて、それぞれに専用の騎乗技術が要るんだが、どれもそれぞれトレーナーを探さにゃならん。\n\n金が十分にたまったら声をかけてくれ。雄羊の乗り方について、わしの知ってることを全部教えてやるよ。", nil, nil, 0x70893089, 0xd951fb2b, 0x44eb15dc, nil, nil, "...mm" },
  [97022] = { "Danithaへの報告", "Bandarion KeepにいるDanitha Morrと話す。", "Danitha Morrから、追加の訓練を受けるためBandarion Keepへ戻って報告するよう命令が出ています。できるだけ早く砦へ戻ってください。", nil, nil, 0x8da1b01c, 0xe99f5883, 0x37976c93, nil, nil, "...mm" },
  [97029] = { "Eluvi'ana", "Ancient Skyborne Bladeについてさらに知るため、それをEalaane Nimbuswalkerに届ける。", nil, nil, nil, 0x81e4c1c3, 0x782a5d21, nil, nil, nil, "..mmm" },
  [97045] = { "初めての馬", "騎乗用の馬を見て回り、最初の乗騎を選ぶ。", "ようこそ！うちの馬を見に来たのかい？\n\nこの馬たちは、由緒あるLordaeronの血統と、この土地の馬の両方の血を引いているんだ。旅の相棒として、これ以上頼りになる相手はいないよ。\n\nどれも優秀で、危険な時でも落ち着いていられるよう訓練されているから、一頭を選ぶのは難しいかもしれない。忘れないで、君と馬は一緒に世界を巡るんだからね。どれを選んでも、きっと君に一番合うはずさ。\n\n馬たちを見に行って、選び終えたら私のところへ戻っておいで。", nil, nil, 0x001ed422, 0x4dfd35cf, 0x158ac1f1, nil, nil, "...mm" },
  [97046] = { "初めてのMechanostrider", "騎乗用のmechanostriderを見て回り、最初の乗騎を選ぶ。", "ごきげんよう！今日はまさに大事な日だね。今日、君は自分の生体データを、初めてのmechanostriderの乗り手認識プロトコルに同期させるんだ！このプロトコルのおかげで、striderは君をほかの乗り手候補と見分けられるようになるのさ。\n\nだから、君は大事な選択をしなきゃならない。君とstriderは一緒に世界を巡るんだから、よく考えて選んでね！心配ご無用、どれを選んでも、それが正しい選択になるよ。\n\nmechanostriderたちを見に行って、選び終えたら私のところへ戻っておいで。", nil, nil, 0xc18e78f9, 0x580b869f, 0xdd6129cd, nil, nil, "...mm" },
  [97047] = { "檻の中の料理人", "Kurzenの拠点で、Wendelの檻の鍵と、彼が抜け出すための変装道具を見つける。", "おい！あんた！助けてくれ！ジャングルを探検してたら、いきなりこの狂った連中に待ち伏せされたんだ！俺をどうするつもりか知らないけど、虎だの首狩りだのって話が聞こえてきて、どっちもごめんだよ！\n\nどうやってかは分からないけど、ここから出してくれ！頼む！この檻の鍵とか、こっそり抜け出すための変装とか、何か！何でもいいから！", nil, nil, 0x2f0f87ce, 0xcbd4ea81, 0x88f0903a, nil, nil, "...mm" },
  [97048] = { "港への帰還", "Booty BayのCaptain Aransasと話す。", "なあ、今はお礼ができないけど、俺はCaptain Aransasの船のコックなんだ。Booty Bayに戻ったら、あんたのことをちゃんと良く言っておくよ。機会があったら船長と話してみてくれ。俺が戻れば彼女はきっと喜ぶさ。", nil, nil, 0xd608f137, 0x2d90b9f5, 0xaaf806d7, nil, nil, "...mm" },
  [97049] = { "染み出すスライムの精髄", "Shaper's TerraceでSeeping Slime Essenceを$N1個集める。", "Shaper's Terraceへ向かうのなら、お願いしたいことがあります。\n\n色のないAchromatic Crystalのそばの池に、スライムが棲んでいるという報告があります。その精髄が私の実験に役立つかもしれませんので、研究用にいくつか試料を持ってきていただきたいのです。\n\nそれに見合うお礼はいたします。", nil, nil, 0x865a3952, 0x756fc3f6, 0x4d0f6b81, nil, nil, "...mm" },
  [97065] = { "天秤を傾けろ - Keefer's Angelfish", nil, nil, nil, nil, 0x9099a156, nil, nil, nil, nil, ".mmmm" },
  [97066] = { "天秤を傾けろ - Brownell's Blue Striped Racer", nil, nil, nil, nil, 0x8c2e8a32, nil, nil, nil, nil, ".mmmm" },
  [97067] = { "天秤を傾けろ - Dezian Queenfish", nil, nil, nil, nil, 0x96bb5eae, nil, nil, nil, nil, ".mmmm" },
  [97074] = { "騎乗を学ぶ", "JartsamからApprentice Ridingのスキルを習得する。", "こんにちは、{class}！あなたはもう、私がsaberの乗り方をお教えできるほど、冒険者として経験を積まれたようですね。もちろん、料金はいただきますが。\n\n私のもとで訓練を受ければ、Lelanaiが乗騎を無料で用意してくれます。その後は、欲しい乗騎を好きなだけ購入できるようになります。世界にはたくさんの生き物がいて、それぞれに専用の騎乗技術が必要ですが、それぞれのトレーナーはご自分で探さなければなりません。\n\nお金が十分に貯まったら声をかけてください。saberの乗り方について、私の知っていることをすべてお教えしましょう。", nil, nil, 0x70893089, 0x343bf588, 0xf22585e5, nil, nil, "...mm" },
  [97119] = { "いよいよ料理だ", "Savory Stag Slidersを$N1個、ElderwildのOrtak Lomgokのもとへ持っていく。", "ここの人々の心の支えになるだけでなく、私は食事の世話もしているんです。きちんと修業した料理人というわけではありませんが、5年もやっていれば、料理について一つや二つは覚えるものですよ！\n\nここの皆さんも、きっと何か違うものを味わいたいはずです。この山に集まる前、Everlookから来たゴブリンが、小さなSavory Stag Slidersを大皿で振る舞っていたのを覚えています……あれをもう一度味わってみたいんです。ここにも雄鹿はたくさんいますしね！いくつか作ってもらえますか？", nil, nil, 0x16762640, 0xcdb1da52, 0x169d1dee, nil, nil, "...mm" },
  [97130] = { "古代Gurubashiの秘密", "Drowned CityからAncient Gurubashi Idolを取り戻す。", "Lan'dalockと私は、南の海での最近の出来事について話し合っていたところだ。Stranglethorn Valeの沖合に、古代Gurubashiの遺跡が突如として姿を現したのだ。\n\nそのような場所には、考古学的に大きな価値がある。古代Gurubashiの一部の呪術医たちが、血の魔法の儀式の焦点として用いていた偶像を、ぜひ一つ手に入れたいと考えている。\n\nこの「Drowned City」に入り、偶像を一つ取ってきてくれ。", nil, nil, 0xefbd092f, 0x4a847e99, 0xab7e1556, nil, nil, "...mm" },
  [97168] = { "素材援助", "IronforgeのEldrun Stormbreakerを手伝う気があるなら、Azerothian DiamondとPristine Black Diamondを彼のもとへ持っていく。", "{name}、霊たちは物質的にも霊的にも重くのしかかっておる。お前さんの助けが要るんじゃ。LordaeronのScholomanceの奥深くに、影の濃いGreat Ossuaryがある。わしはその闇を断ち切る装置を作っておるんじゃが、仕上げる手段が足りん。\n\nダイヤモンドを2つ持ってきてくれ。Azerothianを1つと、Pristine Blackを1つじゃ。どちらもありふれた品ではない、そうとも……ただ、わし自身には手に入れる元手がなくてな。その2つのダイヤモンドを用意してもらえんか？", nil, nil, 0x2664d220, 0xc092eff6, 0x59299744, nil, nil, "...mm" },
  [97169] = { "Darkreaverの脅威", "ScholomanceにあるGreat Ossuaryの地下室の中心でDivination Scryerを使う。そうすると、戦わねばならない霊たちが現れる。その霊たちを倒すとDeath Knight Darkreaverが呼び出されるので、彼を倒す。\n\nDarkreaver's HeadをIronforgeのForlorn CavernsにいるEldrun Stormbreakerのもとへ持っていく。", "Death Knight DarkreaverがScholomanceのGreat Ossuaryを支配しておる。奴は霊界を捻じ曲げて自らの意のままにしようとしておる。止めねばならん！ここで、お前さんが作るのを手伝ったscryerが役に立つんじゃ。\n\nGreat Ossuaryの地下の中心でdivination scryerを使い、Darkreaverの霊の手下どもを呼び出すんじゃ。霊どもを倒せば、死の騎士本人が現れる。{name}、奴の首を持ってきてくれ！奴の死だけが、霊界に与えられた損傷を元に戻せるんじゃ！", nil, nil, 0xf4f3bcea, 0xba92656d, 0x4c7d637c, nil, nil, "...mm" },
  [97170] = { "騎乗を学ぶ", "Randal HunterからApprentice Ridingのスキルを習得する。", "やあ、{class}！どうやら君も、私が馬の乗り方を教えられるくらい、冒険者として経験を積んだようだね。もちろん、料金はいただくけどね。\n\n私のところで訓練を受けたら、Katieが乗騎を無料で用意してくれる。その後は、欲しい乗騎を好きなだけ買えるようになるよ。世界にはたくさんの生き物がいて、それぞれに専用の騎乗技術が必要だけど、それぞれのトレーナーは自分で探さなきゃならない。\n\nお金が十分に貯まったら声をかけてくれ。馬の乗り方について、私の知っていることを全部教えてあげよう。", nil, nil, 0x70893089, 0x1b612170, 0x5d6758f4, nil, nil, "...mm" },
  [97171] = { "初めての馬", "騎乗用の馬を見て回り、最初の騎乗動物を選ぶ。", "ようこそ！馬を見に来られたのですか？\n\nこの馬たちは、歴史あるLordaeronの血統と、この土地の馬の両方を受け継いでいます。旅のお供として、これほど頼もしい相棒は見つかりませんよ。\n\nどの馬も優秀で、危険なときでも落ち着いていられるよう訓練されているので、一頭を選ぶのは難しいかもしれません。忘れないでください、あなたと馬は一緒に世界を旅するのです。どれを選んでも、きっとあなたにぴったりのはずです。\n\n馬を見て、選んだら私のところへ戻ってきてください。", nil, nil, 0x001ed422, 0x4dfd35cf, 0x158ac1f1, nil, nil, "...mm" },
  [97173] = { "Blackmawの魔法", "Blackmaw HoldからBlackmaw Ritual Totemを回収する。", "Azsharaを見下ろす山々に住むBlackmawのfurbolgsが、闇の魔法に手を出している。未開の民が悪魔の魔法に堕落するなど、Azerothでは珍しくもないが、Lan'dalockと私は奴らの呪文の焦点具を研究したいのだ。\n\nBlackmaw Holdと呼ばれる砦へ行き、Blackmaw Ritual Totemsを1つ持ち帰ってくれ。これを持っているのはBlackmawのシャーマンの中でも最も強い者だけだ。仲間を連れて、気をつけて行け。", nil, nil, 0xd8ada7f4, 0xdca24cad, 0xd8ed8c41, nil, nil, "...mm" },
  [97174] = { "価値ある試み", "Tirisfal GladesのBandarion KeepにいるDanitha Morrと話す。", "時は来た、{name}。生前と同じく、Forsakenのパラディンは軍馬と絆を結べるようになって初めて一人前となる。これはただの馬ではない、報復の強大な霊なのだ。\n\n詳しくはBandarion KeepのDanitha Morrと話せ。次にすべきことを彼女が導いてくれる。お前の前の道は険しいだろうが、我らがオークの盟友たちがよく言うように……血と雷を、同胞よ！", nil, nil, 0x402fd91d, 0x1a2c29f4, 0x1c23bcfe, nil, nil, "...mm", nil, nil, 0xc694a950, nil, nil },
  [97175] = { "しかるべき犠牲", "Orgrimmarへ行き、High Priest ZayusのExorcism Censerを手に入れる。それを確保するには150ゴールドを寄付する必要がある。", "価値ある試みで、何の犠牲も払わずに成し遂げられるものはない。そしてこの最初の務めにも、まさにそれが求められる。\n\nお前の務めのために、High Priest Zayusのexorcism censerを手に入れねばならない。正当な目的に使うとはいえ、それに見合う対価は払わねばならない。\n\nOrgrimmarへ行き、そこにいるHigh Priest Zayusと話せ。Zayusはcenserを失う代わりに……「寄付」を求めるだろう。すべてが終われば、安い代償だ。", nil, nil, 0x3e84aca3, 0xe68879ed, 0x02e6b947, nil, nil, "...mm" },
  [97176] = { "Terrordaleの町の除霊", "Exorcism Censerを使って、Terrordaleの苦しむ霊たちを追い払う。Terrordale Spiritsを25体滅ぼしたら、Tirisfal GladesのBandarion KeepにいるDanitha Morrのもとへ戻る。", "Eastern PlaguelandsのTerrordaleの穢れた地面から取った土を、censerに加えておいた。そこへ行き、このcenserを使って、最も強い穢れの兆しがある場所を探し出せ。そうした場所は、苦しむ魂たちが集まる地点の地面から立ち上る、緑色の死の霊気で分かるだろう。\n\ncenserを使ってこれらの霊を明らかにせよ。奴らを苦しみから解放するのだ。魂たちを安らかに眠らせたら戻ってこい。次の段階について話そう。", nil, nil, 0xb8674f67, 0x99847261, 0x5c3f0c74, nil, nil, "...mm" },
  [97177] = { "慈悲の行い", "Exorcism CenserをTirisfal GladesのBandarion KeepにいるDanitha Morrのもとへ返す。", "ロアの祝福と共に、このcenserを持っていきな。俺はこれで悪いブードゥーの霊を何度も祓ってきた。これから来る試練でも、きっとお前さんの役に立つだろうよ。\n\nそろそろDanithaのところへ戻った方がいいぜ、{name}。お前さんのクエストは彼女のもとで続くんだ。", nil, nil, 0xfee28d3f, 0x323486ba, 0xea1025c3, nil, nil, "...mm" },
  [97178] = { "Tarren MillのOtt", "Hillsbrad FoothillsのTarren Millの村にいるOttと話す。", "パラディンの軍馬には、ふさわしい馬鎧が必要だ。それがなければ、軍馬は心なき獣とさして変わらぬ。お前の軍馬の馬鎧は、可能な限り最上の素材で作られねばならないだけでなく、霊界との同調にも適したものでなければならない。\n\nTarren Millの外れに、かつて我らのパラディンのために素晴らしい仕事をした鍛冶がいる。控えめで飾らないオークだが、腕は見事で、我らの求めにもよく合う。彼を訪ね、この仕事を依頼せよ。", nil, nil, 0xb7610888, 0xabd4c144, 0x4ac46d23, nil, nil, "...mm" },
  [97179] = { "材料集め", "Runeclothを40枚、Arcanite Barsを6本、Arthas' Tearsを10個、Stratholme Holy Waterを5瓶、そして150ゴールドを、Hillsbrad FoothillsのOttのもとへ持っていく。", "馬鎧にはいくつか必要な物がある。裏地にはrunecloth、板金にはarcanite bars、霊的な同調にはArthas' Tears、霊的な力を込めるにはStratholme holy waterだ。最後に、手間賃と、馬鎧に合わせる鞍と鐙の代金として、ささやかな料金をいただく。\n\nこれらの材料を持ってきてくれれば、馬鎧を仕上げられる。お前が材料を集めている間に、俺は鞍に取りかかっておこう。", nil, nil, 0x85fed7c1, 0x8f97760a, 0x14e6f591, nil, nil, "...mm" },
  [97180] = { "Ottの最高傑作", "検査のため、Arcanite BardingをBandarion KeepのDanitha Morrのもとへ持っていく。", "<Ottは額の汗をぬぐい、満足げに自分の仕事を見てうなる。>\n\n来たか。俺の商売はたいてい武器作りだが、それでもこれは俺の最高の仕事の一つかもしれん。お前とお前の仲間のパラディンたちが俺を信頼してくれたことに感謝する。\n\nDanitha Morrもきっと自分の目でこの仕事を確かめたいだろう。馬鎧を彼女のところへ持っていき、お前のためにこの依頼を果たさせてくれたことへの礼を伝えてくれ。\n\nLok-tar、{class}。", nil, nil, 0xb51868fb, 0xf8c175c9, 0x97dfc029, nil, nil, "...mm" },
  [97182] = { "復讐の捧げ物", "霊馬に与えるための特別な馬の飼料を手に入れる。Eastern PlaguelandsのNathanos Blightcallerなら、そうした飼料を用意できるかもしれない。\n\nFeralasのDire Maulへ行き、Tendris Warpwoodを倒す。そうすればAncient Equine Spiritが解放される。特別な馬の飼料を与えて、それをなだめる。\n\n最後に、Arcanite Bardingを渡し、必要な祝福を与えてくれることを願う。", "パラディンの軍馬の馬鎧には、強大な馬の霊の祝福が必要だ。Dire Maulの遺跡では、Tendris Warpwoodとして知られる堕落したトレントが、そのような霊を囚えている。この霊に代わって報復を果たし、その束縛から解き放て。うまくいけば、霊は祝福を授けてくれるかもしれない。\n\n成功を確かなものにするため、霊的に同調した特別な飼い葉も持っていくよう勧める。Eastern Plaguelandsへ行き、Nathanos Blightcallerとして知られるレンジャーとこの件について話せ。", nil, nil, 0xde30e4a4, 0xb6a2ffd6, 0x8ea53502, nil, nil, "...mm" },
  [97183] = { "Blessed Arcanite Barding", "Blessed Arcanite Bardingを持って、Tirisfal GladesのBandarion KeepにいるDanitha Morrのもとへ戻る。", "馬鎧をAncient Equine Spiritの背に載せると、それは白熱して輝く。ほんの一瞬、空気が力に満ちて重くなり、やがて馬鎧は馬の背から消え、あなたの背負い袋の中に収まっている。\n\n鞄の革越しにも、鞍からまだ熱が伝わってくるのを感じる。どうやら復讐の捧げ物は受け入れられ、馬鎧は祝福されたようだ。Bandarion KeepのDanitha Morrのもとへ戻る時だ。", nil, nil, 0xcd7cadda, 0xb8276b39, 0x99801d9d, nil, nil, "...mm" },
  [97184] = { "Divination Scryer", "Azerothian DiamondとPristine Black DiamondをTirisfal GladesのBandarion KeepにいるDanitha Morrのもとへ持っていく。", "次に、お前の最後の試練に欠かせないDivination Scryerを組み立てねばならない。お前がTerrordaleで使ったexorcism censerがその触媒となる。占いの装置にふさわしい器は、私が作れるはずだ。\n\nだが、最後に必要な部品は2つのダイヤモンドだ。白を1つ、黒を1つ。これはThe Forsakenのパラディンとしての我らの本質の二面性を表している。この2つが道しるべとなり、scryerが生者と死者を隔てる帳を貫くのだ。", nil, nil, 0x97882862, 0xe64571b3, 0xfa1703d5, nil, nil, "...mm" },
  [97185] = { "正義と報復", "ScholomanceにあるGreat Ossuaryの地下室の中心でDivination Scryerを使う。そうすると、裁かねばならない霊たちが現れる。その霊たちを倒すとDeath Knight Darkreaverが呼び出される。彼を倒し、倒れた軍馬の失われた魂を取り戻す。\n\nSpirit of RetributionとBlessed Enchanted BardingをDarkreaver's Fallen Chargerに渡す。", "この鞄に、試練に必要な品が入っている。Great Ossuaryの地下の中心でdivination scryerを使い、呪われた霊たちを呼び出して裁きを受けさせよ。この戦いではお前の裁きの力が非常に役立つだろう。賢く使え。\n\n霊たちを散らせば、Darkreaverが現れる。奴を倒し、軍馬の失われた魂を取り戻せ。お前の歩む正義と報復の道を見せてやれ。うまくいけば、魂はお前の傍らに居場所を得るだろう。", nil, nil, 0xd7a36f70, 0xf593f040, 0x5575ccb6, nil, nil, "...mm" },
  [97186] = { "Manna-Enriched Horse Feed", "Eastern PlaguelandsのNathanos BlightcallerのためにEnriched Manna Biscuitsを20個手に入れる。Enriched Manna Biscuitsを扱っているのはArgent Dawnだけだと知られている。また、手間賃としてBlightcallerに50ゴールドを渡す必要もある。", "では、実体のない馬の霊に与える飼い葉が要るというのか？面白い。\n\nああ、必要なものなら手を貸せるだろう。私は相当な時間をかけて獣を育ててきた。その獣たちは……そうだな、もはや完全にはこの世のものではない、とでも言っておこう。奴らを生かしておく方法なら、一つや二つは心得ている。\n\nArgent Dawnが売っている、霊的に滋養を高めたビスケットがいくらかあればいい……それと、わずかなゴールドの捧げ物だ。もちろん、私の手間賃としてな。", nil, nil, 0x1f21fe01, 0x3feebf8f, 0x74c26f68, nil, nil, "...mm" },
  [97188] = { "騎乗を学ぶ", "Binjy FeatherwhistleからApprentice Ridingのスキルを習得する。", "ごきげんよう、{class}！君はもう、私がmechanostriderの操縦を教えられるくらい、冒険者として経験を積んだね。もちろん、料金はいただくけどね。\n\n私のところで訓練を受けたら、Milliが乗騎を無料で用意してくれる。その後は、欲しい乗騎を好きなだけ買えるようになるよ。世界にはたくさんの生き物がいて、それぞれに専用の騎乗技術が必要だけど、それぞれのトレーナーは自分で探さなきゃならない。\n\nゴールドが十分に貯まったら声をかけてくれ。mechanostriderの乗り方を教えてあげよう！", nil, nil, 0x70893089, 0xad9acccd, 0x61e48e2a, nil, nil, "...mm" },
  [97194] = { "騎乗を学ぶ", "KildarからApprentice Ridingのスキルを習得する。", "Mok'ra、{class}。お前も冒険者として経験を積んだようだな。俺たちの狼の乗り方を教えてやれるくらいにはな。もちろん、料金はもらうぞ。\n\n俺のもとで訓練を受ければ、Ogunaroが乗騎をただでくれる。その後は、欲しい乗騎を好きなだけ買えるようになる。世界には多くの生き物がいて、それぞれに専用の騎乗技術が要るが、それぞれのトレーナーは自分で探さねばならん。\n\nゴールドが十分にたまったら声をかけろ。狼の乗り方を教えてやる。", nil, nil, 0x70893089, 0xef07a3aa, 0xc830bf6d, nil, nil, "...mm" },
  [97196] = { "The Coldbringer's Eye", "Razorfen DownsからThe Coldbringer's Eyeを取り戻す。", "Razorfen Downsと呼ばれるDeath's Headのquilboarの巣窟の奥深くに、Lich Kingの僕が住み着いている。奴が遠見の宝珠を使い、よそにいる手下どもの動きを見張り、指図していることは、我々も把握している。\n\nこの秘宝があれば、Scourgeの密偵どもを狩り出し、奴らとKalimdorに及ぼす脅威を永遠に終わらせることができるだろう。\n\nRazorfen Downsに入ってAmnennar the Coldbringerの巣窟へ向かい、Coldbringer's Eyeと呼ばれる宝珠を取ってきてくれ。", nil, nil, 0x807d643a, 0xc02af882, 0xbaa21f1d, nil, nil, "...mm" },
  [97197] = { "Fragment of the Firelands", "MulgoreのAlaana StormwalkerのためにBlackrock DepthsからFragment of the Firelandsを回収する。", "Mulnの話では、Blackrock Mountainと呼ばれる場所の最深部に、Azerothと元素界の間の障壁が損なわれた所があるそうです。そこからFirelandsの領域の無数の元素の生き物がこの現実へ逃げ出していて、その中にはAnchor Pylonほどもある巨人までいるとか！\n\nそうした生き物から集められる物質の欠片なら何でも、ぜひ研究したいのです。Blackrock Depthsに挑んで、私のために試料を持ち帰ってくださいませんか？", nil, nil, 0x5792e331, 0xe1878c9e, 0x4f267383, nil, nil, "...mm" },
  [97198] = { "Blackmawの魔法", "Blackmaw HoldからBlackmaw Ritual Totemを回収する。", "Azsharaを見下ろす山々に住むBlackmawのfurbolgsは、暗く邪な魔法に堕落してしまった。その堕落がどこまで及んでいるのか、そしてこの地の元素にどんな影響を与えうるのか、全容は分からないが、よりよく理解したいと思っている。\n\nBlackmaw Holdと呼ばれる砦へ行き、Blackmaw Ritual Totemsを1つ持ち帰ってくれ。これを持っているのはBlackmawのシャーマンの中でも最も強い者だけだ。仲間を連れて、厳しい戦いに備えよ。", nil, nil, 0xd8ada7f4, 0xdca24cad, 0x5956898f, nil, nil, "...mm" },
  [97200] = { "騎乗を学ぶ", "Xar'tiからApprentice Ridingのスキルを習得する。", "よう、ようこそ{class}！お前さんも冒険者として十分経験を積んだから、俺らのraptorの乗り方を教えてやれるぜ。もちろん料金はいただくがな。\n\n俺の訓練を受けたら、Zjolnirがタダで乗騎を一頭くれる。その後は、好きなだけ追加の乗騎を買えるようになる。世界にはいろんな生き物がいて、それぞれに専用の騎乗スキルが要るが、それぞれのトレーナーは自分で探さなきゃならねえ。\n\nゴールドが十分貯まったら声をかけな。raptorの乗り方を教えてやる。", nil, nil, 0x70893089, 0xa1231880, 0xfa7333cd, nil, nil, "...mm" },
  [97203] = { "騎乗を学ぶ", "Velma WarnamからApprentice Ridingのスキルを習得する。", "ようこそ、{class}。どうやらお前も、私が骸骨の馬の乗り方を教えられるくらい、冒険者として経験を積んだようだな。ただし、料金はもらう。\n\n私のもとで訓練を受ければ、Zachariahが乗騎を無料で用意する。その後は、望むだけ乗騎を買えるようになる。世界には多くの生き物がいて、それぞれに専用の騎乗技術が要るが、それぞれのトレーナーは自分で探さねばならない。\n\n金が十分にたまったら声をかけろ。骸骨の馬について教えてやろう。", nil, nil, 0x70893089, 0xc805e1bc, 0x56b28782, nil, nil, "...mm" },
  [97204] = { "騎乗を学ぶ", "Kar StormsingerからApprentice Ridingのスキルを習得する。", "よく来た、{class}。どうやらそなたは冒険者として十分に経験を積み、kodoの乗り方を学べるまでになったようだな。もちろん、料金はいただく。\n\n我がもとで訓練を受ければ、Harbが乗騎を無料で用意してくれる。その後は、望む乗騎を好きなだけ買えるようになる。世界には多くの生き物がおり、それぞれに専用の騎乗技術が要るが、それぞれのトレーナーは自ら探さねばならぬ。\n\n金が十分にたまったら声をかけるがよい。気高きkodoの乗り方を教えよう。", nil, nil, 0x70893089, 0xc691cd57, 0x244c8bec, nil, nil, "...mm" },
  [97205] = { "騎乗を学ぶ", "Genn FairweatherからApprentice Ridingのスキルを習得する。", "やあ、{class}！どうやらあなたも、冒険者として十分に経験を積み、galestriderの乗り方を学べるまでになったようですね。もちろん、料金はいただきますが。\n\n私のもとで訓練を受ければ、乗騎を無料でご用意します。その後は、欲しい乗騎を好きなだけ購入できるようになります。世界にはたくさんの生き物がいて、それぞれに専用の騎乗技術が必要ですが、それぞれのトレーナーはご自分で探さなければなりません。\n\nお金が十分に貯まったら声をかけてください。galestriderの乗り方をお教えしましょう。", nil, nil, 0x70893089, 0x21d2f84c, 0x42a137db, nil, nil, "...mm" },
  [97220] = { "Philmorの頼み", "Gatehouse Shipmentを、Trade DistrictにあるTrias' Cheeseの店内の倉庫の入り口へ持って行って下さい。", "今週は毎日、荷役が足りないんです。\n\nうちの荷物の予定の負担を軽くしてもらえませんか？\n\nこの包みをGatehouseの倉庫の入り口へ持っていってください。二階のTrias' Cheeseの店の中にあります。女主人のElaineが配達のことはよく知っていますよ。Gatehouseには、衛兵の士官たちのための儀礼的なサプライズのために、控えめに届く荷物がよくあるんです。", "うちの極上の熟成チーズを、木箱いっぱいに詰めたいのかい？", "おやおや。私たちがそれを自分で階段の上まで運ぶとでも思っているのかい？ 預け終えるまで、貴重品を無傷に保つのはあなたの責任だ。", 0xcadc7a51, 0x77beb6bd, 0x756a7024, 0x0f6c2b4b, 0xfbcc083f, "....." },
  [97222] = { "Gatehouseの品", "Gatehouse ShipmentをTrias'の店の階段の上へ運び、扉の外に置いてください。", "ええ、階段をひとつ上がるだけだけど、そんなに小さな頼みなら、配達を自分で最後までやってくれても問題ないでしょう！\n\nTrias' CheeseはGatehouseの一部でもないし、あそこの在庫でもないけど、うちの建物は同じ階なの。\n\n木箱を倉庫の扉の外に置いておいて。衛兵がいつもの受け取りに誰かを寄こすから。荷物が届いているのを見たら、持ち場に戻る時に中へ運び込んでくれるわ。", "せめてこの熟成チェダーを少し試してみなよ。食べだしたら止まらないよ。", "ああ。あの蝶番が向こう側へ内開きになっているのには理由がある。そこらじゅうに物を置いていく連中に扉をふさがれないようにな。\n\nこれで仕事上の顔見知りってことだ、{class}。\n\nこっちはあんたの商売を尊重する。だからあんたもこっちの商売を尊重してくれ。", 0x2ad17834, 0xd062b437, 0x4288f8d0, 0xc9e39695, 0xb35fbfba, "....." },
  [97223] = { "Bloodtalonの母獣", "Eggs of the Bloodtalon MatriarchをSen'jin VillageのXar'Tiに届けてください。", "目の前にいるラプターは、どれも私が自分で育てたものだ。Kalimdor中から集めたが、中でも上等なのは、我らの海岸沖の島々にいるBloodtalonのラプターだ。\n\nその中の一頭、Bloodtalon Matriarchは特に凶暴で、我らの村の者を大勢殺し、境に放っておくには危険すぎる存在になった。そいつを倒せたら、その卵を持ち帰ってくれ。雛を敵ではなく味方として育てられるようにな。", "Bloodtalonは賢さと素早さで知られ、卵から大人まで育てれば立派な相棒になる。\n\nあいにく大人のraptorを手なずけるのはとても難しくてな、Matriarchを捕まえようとしたことも一度や二度ではない。だが、近頃のあいつは危険になりすぎていた。\n\nそれでも、ここSen'Jinであいつの子らを相棒として育てて、その血筋を残したいと思っている。", "ありがとう、{name}。彼女の血統を守り、あの子たちを私たちの仲間として育てられることを嬉しく思う。お前は私たちの部族に大きな貢献をしてくれた。", 0x04cfeed5, 0xc4b71826, 0xb9b4e0b5, 0xa423bd09, 0x25bba0d6, "....." },
  [97225] = { "Forgotten Loa Idols", "Echo IslesでForgotten Loa Idolを$N1個集めてください。それをSen'jin VillageにいるMaster Gadrinのところへ持って行ってください。", "Zalazaneとその一味が今住みついている島々から逃げた時、我らはたくさんの大切な像を置いてきてしまった。我らが崇める精霊、loaと心を通わせるための像だ。それらは我らの部族にとって極めて重要なものだ。\n\nZalazaneの手下どもは我らのloaに何の敬意も払わず、その像を一番大きな島じゅうにばらまいてしまった。\n\nこの像を集められなければ、この仕打ちは見過ごされはしないだろう。loaの機嫌を損ねるのは重大なことなのだ。\n\n行け、loaの像をできるだけ多く見つけて、我のもとへ持ち帰ってくれ。", "わしらのロアの像は見つかったか、{name}？早く儀式を再開せねばならん。", "お前は今日、私たちの部族のために大きな功績を挙げた。\n\n他の部族とは違い、私たちとloaとの絆は敬意と尊重に基づくもので、私たちはloaに多くを負っている。\n\nDarkspearがloaの不興を買うようなことにはしたくない。", 0x3a6e02f8, 0xd654e4c4, 0x689f1998, 0x682f9535, 0x0b095262, "....." },
  [97234] = { "閲覧室", "包まれた読み物をStormwindの図書館へ届けてください。", "私たちの由緒ある伝説の深い意味について語り合いに来たのですか？ 違う？\n\nでは、見て回るのが済んだら、これを図書館へ運んでもらえませんか？ あまり人気のない蔵書の一部を、もっと現代的な書き物と交換しているところなのです。今の取り決めの範囲で司書がきっと用意してくれるはずの本の一覧があるのです。\n\n手伝ってくれたら、クラブの軽食をごちそうしますよ。", "声を落としてください。", "どれどれ。Roy's Book Clubですね？ この包み方には見覚えがあります。\n\nまあ、皆が話し合いたいのがこれだと彼が言うのなら、私は一向に構いません。返却される資料はいつも貸し出した時と同じくらい良い状態ですから、言葉がどれほど刺激的であろうと、彼らが敬意を持って扱っているのは分かっています。", 0x3eee958f, 0xfdbaaa05, 0x221f294c, 0xaee85b9a, 0x453e623d, "....." },
  [97236] = { "Fang of Githyiss", "Fang of GithyissをAldrassilで蜘蛛の研究に関心のある人物に届ける。", "これほど大きな獣の新鮮な標本は、なかなかの掘り出し物だ。Aldrassilで蜘蛛の研究に通じている誰かなら、この牙に興味を持つかもしれない。", nil, "おやおや。私は驚かされるのが本当に大好きでね、{name}。\n\nこの標本はきっと私の研究をさらに進めてくれるだろう。", 0xc0cb6394, 0xe6a4e5ad, 0x9adc9237, nil, 0xd5fbb580, "...m." },
  [97237] = { "棚探し", "図書館のどこかにある読み物をすべて見つけ、Stormwind's ParkのRoy Lewellsのところへ戻ってください。", "在庫を確認しましたが、Mr. Lewellsが一覧に挙げた本はすべて今そろっております。\n\nただし、棚からはご自分で取っていただく必要があります。私ども司書の務めの一部は目を光らせることですので、私は監督の帳簿付けに戻らせていただきます。\n\nRoy様の代わりに資料を持ち帰っても、あなたが返却の責任を負うことにはなりません。彼の書き付けにある通り、あなたは読書会の公式な使いを務めているのです。その責任は先方の会が負います。\n\nごきげんよう、{name}。", "扉をくぐった途端、何をしなきゃいけなかったか忘れちまったんだろ？ 誰にでもあることさ。", "これだ、これ！ 中には異国の香りがするものまである！ 素晴らしい、これらの書き物について皆で活発に語り合うのが待ちきれないよ。\n\nもちろん、閉店後の地下室でね。\n\nさっとお使いを済ませてくれてありがとう、{name}。約束どおり、代金はいらないよ。うちは約束を守るんだ。", 0xa2b3432f, 0xa187b795, 0x7efc8438, 0x6507ccfd, 0xac97da81, "....." },
  [97242] = { "YelmakのMedley", "Valley of Honorの水の流れの周りに生えているCattailsとSpeargrassを少し刈り取り、Yelmak's Alchemy and PotionsのKor'geldのところへ戻って下さい。", "Yelmakは弟子にものを壊してほしくないのさ。まあ、もうすでに壊した分よりはね。\n\nあの若い見習いの調合師は、本当に助けが要る時でもプライドが高すぎて頼めないんだって、Yelmakが言ってた。Yelmakはあの子に、ある自家製の調合を味わわせてやりたいんだよ。\n\nValley of Honorの水辺に生えているガマとヤリクサを刈り取って、混ぜて集めてきてくれ。自分で取りに行きたいところだけど、店を離れたら、Whuutのご機嫌取りをしてるって絶対にばれちまうからね。", "わしらは、古い材料を新しい世代に見せることで調合法やレシピを見いだすのさ。若い者は自分なりのやり方でそれを試すからな。", "この種類のガマとヤリクサは、Orgrimmarにしか生えん。Azsharaの山の湧き水を飲み、わしらの岩だらけの土地の、汗と血のしみ込んだ鉱物の塵に養われて、この薬草は内に強い力を秘めておるのだ。\n\nこれはYelmakに渡しておこう。実地の手ほどきで、Whuutにもう一度耳を傾けさせられるかもしれん。", 0x90c5761e, 0xc53ac54f, 0xb4681896, 0xaeb14159, 0x19d48937, "....." },
  [97243] = { "火の呼び声", "Torch of Dormant Flameを、Gustberry LowlandsのShrine of FlamesにいるOlariaan Swiftburnに届けてください。", "ここはSkywallの領域とはいえ、精霊界であることに変わりはありません。耳を傾けようとさえすれば、4つの元素すべての精霊が我々に語りかけてくるのです。我々Windshapersの中に、火の元素ととりわけ深く通じ合っている者がいます。Olariaan Swiftburnという名のshen'doreiです。\n\nこれをGustberry LowlandsのShrine of Flamesにいる彼のもとへ届けてください。Valanaarの西、島の端に沿ってひっそりとあります。", "どうした、{name}？そこに何を持っている？", "松明を持ってきたのだな。よかろう、若き{class}よ、火の呼び声に応える術を教えよう。容易ではないが、この世界で我らの成すことに容易なものなど何一つないのだ。", 0x53f3b76b, 0x10e8fa30, 0xb32aea3b, 0xacd1e0ef, 0x89691ed7, "....." },
  [97244] = { "火の呼び声", "Gustberry LowlandsでSkypriest Faladielを倒し、Faladiel's Heartを手に入れてください。", "FaladielというAl'Aketh Skypriestがいる。かつては炎を呼ぶ者であり、忠実なWindshaperだった。多くのAl'Akethと同じく、奴は力のために忠誠を売り渡し、その手は今やかつての兄弟姉妹の血に染まっている。\n\nSkypriest Faladielは、Valanaarを越えた北東の農場、Shrine of Akirのすぐ南にいる。裏切り者を殺せ。その心臓を持ってこい。むごい仕事だが、我々が行う儀式に必要なのだ。", "裏切り者の心臓は強力な秘薬だ。炎はそのような捧げ物を喜んで受け入れ、それを喰らうほどに激しく燃え上がるだろう。", "Windshapersは忘れない。血は常に血で贖われる。この裏切り者に、我らの信条を最後の痛ましい形で思い知らせてくれたことを嬉しく思う。\n\nだが、今日炎にくべるのはこの心臓だけではない。もう一つ、果たさねばならない務めがある。", 0x53f3b76b, 0x7c8f63a5, 0x8ff65707, 0x6c645a00, 0xd212b24c, "....." },
  [97245] = { "火の呼び声", "Shen'dar HighlandsでKuramaaの住処を見つけ、その霊を戦いで打ち負かしてください。勝利したら、Kuramaa's MaskをGustberry LowlandsのOlariaan Swiftburnに届けてください。", "Shen'dar Highlandsの住民は、Kuramaaという古い森の精霊のことを語る。highlandsのAnchor Pylonに近い丘の頂上で、ねじれた切り株の中に住んでいるそうだ。\n\nhighlandsへ行って、その切り株を探せ。樹皮を拳で叩けば、Kuramaaが現れる。その精霊を戦いで打ち負かし、木の仮面を持ってきてくれ。\n\nだが気をつけろ。そいつにはお前の魔法の多くがほとんど効かないだろう。精霊を倒せるのは炎の力だけだ。", "Kuramaaの魂は永遠であり、必要とされる時に再び姿を現すだろう。その仮面は大いなる力の源であり、我々が成し遂げねばならぬ儀式に欠かせぬものとなろう。", "必要なものは揃った。永遠の炎を灯し、火の精霊たちと交わろう。", 0x53f3b76b, 0xf10b3312, 0x5b054c6d, 0x9a2396be, 0xe1d99925, "....." },
  [97246] = { "食事のお願い", "Borstan's Firepitを訪ね、ThatogからMigiの昼食を直接本人に届けるよう頼まれたと伝えてください。", "うちの息子のMigiは、いつも一日中友達と遊びに出かけてしまうの。Borstan'sでお昼を受け取るように言っているんだけど、ほとんどそうしてないのはわかってる。お腹をぺこぺこにして帰ってくるから。子供たちったら、自分の体より遊びの方が大事だと思ってるんだから！\n\nどうか、Borstan's Firepitに寄って、Migiのお昼を届けに来たって伝えてくれる？ Migiはたぶん、Grommash Holdの裏で友達と一緒にいるはずよ。\n\n私は昼間は仕事でここを離れられなくて、あの子の食事を一回一回見てやれないの。", nil, "もちろんだ。Migiの両親とは、毎日あの子に弁当を渡す約束をしているんだが、本人が取りに来てくれないと、食べさせてやれないんだよ。\n\n週に何度も取りに来ないことがあってね。いったいどこから外で遊び回る元気が湧いてくるのやら。", 0xa80c265e, 0x658ca813, 0x194a00ed, nil, 0x6256c34b, "...m." },
  [97249] = { "大好物", "Migi's LunchをGrommash Holdの裏にいる彼のところへ持って行って下さい。", "あの子の親が、腹をちゃんと満たしてるか心配してるってわかったからには、いい考えがあるぞ。\n\n毎日同じ飯を詰めないって約束させられたんだ。Migiが一つのものだけじゃなく、いろいろな味を好きになるようにってな。それでも、燻製器がいっぱいで甘辛いタレの豚バラサンドを作ってる時は、あいつは必ず昼に顔を出すんだ。で、残ったカリカリのタレの切れ端を砕いてトッピングにし始めた。これなら毎日のせられるからな。\n\nこれを届けてやってくれ。そのうち早めに来て、友達も連れてくるようになるかもな！", "こいつは勝てると思うんだが……", "Borstan's Meats？ 僕たちの誰かの分？\n\nあっ！\n\nわあ……すっごくいいにおい！ おいしそう。\n\nお昼ごはんを持ってきてくれてありがとう。友達とGrommash Holdへの道を歩くとき、においだけでBorstanが毎日何を出すか分かるんだ。これ、僕の大好きな甘いグレーズの味がする！ でもちょっと違う。この味の濃いパン粉、好きだな。\n\n毎日こんなにおいしいなら、遊ぶのを中断して、みんなでお昼を食べなきゃね！", 0xd08fbe54, 0x1d99228e, 0x407189ff, 0x603e2035, 0x24d63088, "....." },
  [97250] = { "濡れ衣と正しき是正", "Dustwallow Marshとの境からBarrensに侵入してくるAllianceの兵士を倒し、Camp TaurajoのGrunt Logmarのところへ戻ってください。", "旅の方、Dustwallow Marshへ向かうつもりはありますか？ 人間の兵士が数人、その境界に陣取って、我らトーレンの先導者たちが残した目印を倒していると耳にしたのです。\n\n噂では、人気の酒場が焼け落ちたそうで、いかにもAllianceらしく、奴らはすぐさまHordeに罪をなすりつけたのです！ その言い分に真実があるのかは知る由もありませんが、我らの土地への侵入を許すわけにはいきません。\n\nまず殺せ、調べるのはその後だ！", nil, "やはり噂は本当だったか！ 予想はしていた。東の沿岸ではしばらく前から緊張が高まっていたからな。いずれ争いが我々の領域にまで及ぶのは時間の問題だと分かっていた。\n\nだが、酒場の破壊に我々が関わっていたという話には懐疑的だ。あの道を交易や旅に頼っているHordeの民間人はあまりに多い。時間があれば、さらに調べてみてくれ。\n\nいずれにせよ、今日の働きはHordeの勝利であり、Allianceへの厳しい警告だ！", 0xe1de8387, 0x62527451, 0x121cc5dd, nil, 0xe0593283, "...m." },
  [97253] = { "部品とかけら", "Ratchetの南にある上の海賊キャンプからHandfuls of Complicated Partsを$N1集め、RatchetのWrenix the Wretchedのところへ戻る。", "やあ、ちょっといい？\n\nどうやら、最近の海賊問題の対処に送り込んだ連中が、誰ひとり生きて帰ってきてないんだよね。5、6回やってみた後で思ったんだ。「代わりに機械を送ったらどうだろう？」ってね。ところが、いざとなるとシミターってのはドライバー代わりにもなるらしくて、帰還させる前に、もうバラバラにされて奴らの野営地じゅうに散らばってたんだよ！\n\nその部品を取り返したいんだ。ちょっとした回収任務だから、君が生き残る見込みは他の連中よりずっと高いと思うよ。どうだい？", "ポケットで金がジャラジャラ鳴るまで、一言もしゃべるな！", "うおおおっ！ やるじゃないか、相棒！ おかげでGagsprocketの金属代についての耐えがたい説教をまた聞かずに済んだよ。それより何より、すぐに次の試作品作りに取りかかれる。\n\nえーっと、報酬のことは考えてなかったんだけど……箱は好きかい？", 0xc374d63c, 0xdd7fd206, 0xd685419d, 0xedc33a12, 0x0ab437e0, "....." },
  [97257] = { "火の呼び声", "OlariaanがBrazier of Offeringで儀式を始めるのを待ち、彼の指示に従ってください。\n\n時間切れになる前に、Eternal FlameをValanaarへ届けなければなりません。", "では儀式を執り行う。\n\n材料を祭壇に置き、炎の精霊を呼び出す。捧げ物が受け入れられれば、彼らが現れてEternal Flameに火を灯すだろう。そうしたら松明を掲げ、その炎を捕らえるのだ。\n\n火の灯った松明をValanaarへ運び、Brazier of Eternal Flamesに置け。急がねばならない。Firelandsの炎は、ここSkywallではすぐに消えてしまうのだ。", "ここまでよく来てくれた。君はWindshapersに名誉をもたらしている、{name}。", "終わった。Eternal Flameが再び燃え上がる。\n\nこれでお前の試練は完了だ。Fire Totemを授けよう。旅の中でこの力の象徴を正しく使うのだ、{name}。\n\nただ覚えておけ。精霊界の力は、それを敬う者には仕え、敬わぬ者は焼き尽くす。これが我らの道だ。", 0x53f3b76b, 0x0208cd7e, 0x4a530335, 0x6aa6ef08, 0xaed39338, "....." },
  [97263] = { "お荷物が届きました", "Eldrunがどこかへやってしまった荷物を届けてください。", "<郵便箱のそばに、置き忘れられた包みがいくつかある。そのうちのひとつに、Aerie PeakからIronforgeのEldrun Stormbreakerへの配達と記されていることに気づく。「至急」と書かれている。>", "そこに持っているのは何だ？", "なんだと！ この荷物を探して、毎日銀行のそばの郵便受けに通ってたんだぞ！ この街は造りをなんとかするべきだ。Aerie Peakみたいに分かりやすくないんだからな！\n\nどれどれ、何が入ってるか……トーテム彫りの道具……予備の斧……何かのゴブリンの装置？ そんなもの注文してないぞ！ まあ、送り返せばいいか。\n\nえっと……その、つまり……これを全部届けてくれてありがとうな。手間をかけた礼に、ちょっとしたものだ。", 0xb90615cc, 0x0f13a33f, 0xc3642e31, 0xdcbf39a7, 0xa4d81308, "....." },
  [97264] = { "Shardtoothの抜歯", "周辺の地域からElder Shardtoothを$N1体排除し、Sarna Brownhornのもとへ戻る。", "Shardtoothは季節ごとに凶暴さを増している。奴らは互いに、そして野の捕食者たちと、届く限りのわずかな食料を奪い合っている。\n\nますます頻繁に、身を切る寒さの中、飢えに駆られて我々を襲ってくる。\n\n熊どもは数が多く、意志も強い。数を減らしてやれば、残った家族はかつてないほど強くなるだろう。\n\n奴らの行く道を助けてやれ。最も年老いた者たちを間引くのだ。", nil, nil, 0x0119e46b, 0x3e42bb28, 0xfdb28fa2, nil, nil, "...mm" },
  [97265] = { "Hatefuryに憎しみを", "DesolaceのSargeronで様々なHatefuryのサテュロスを倒し、その後Shadowprey VillageのAka'raiのところへ戻って下さい。", "サテュロスと取引したことはあるか、なあ？\n\nオレはある。断れるわけがねえだろ？ 力の約束、どんな平凡な書物にも載ってねえほどの知識……おまけに、やる気満々で魅力的な手下までついてくる。これ以上何を望むってんだ？\n\nフン、もちろん奴らが定命の者にひざまずくはずがねえ。何も持ってねえときに取引して、さらに何もかも失って捨てられたのさ。\n\n今、オレは復讐がしたい。Hatefuryへの復讐だ。北東にある奴らの野営地を襲え！ 奴らの汚らわしい血で大地を染めてやれ。", nil, nil, 0x80d3ee17, 0x24ba3490, 0x9c7d33bf, nil, nil, "...mm" },
  [97270] = { "Maulでの乱闘", "Dire MaulのMaulの上にいるGriniblix the Spectatorと話す。", "Maulにはこれ以上の何かがあるはずだ！\n\nDire Maulで催しを取り仕切っている、あのやかましいSpectatorなら知っているかもしれない！", nil, nil, 0x1baf941e, 0x5af075c5, 0x3c04074a, nil, nil, "...mm" },
  [97271] = { "Maulか、無か！", nil, nil, nil, nil, 0x4cd0dd21, nil, nil, nil, nil, ".mmmm" },
  [97275] = { "何をそんなに急ぐ", "Yelmak's PotionをWhuutに渡してください。", "Whuutは天才だ。それは確かだ。だが、錬金術の手順を尊重するすべを知るだけの経験も、知恵も、かき混ぜ棒を握ってきた時間も、まだ足りん。\n\nあいつは、手元にある最も希少で珍しい試薬を片っ端から使い果たしていて、立ち止まって基本の技を練習し磨こうとしない。\n\nわしが手早い強壮剤の手法で作ったこの薬を、あいつに渡してくれ。地元の治療薬と丁寧な手つきこそが最初の真の熟達だと知れば、自分のやっていることをすべて考え直すだろう。", "さてと、次は……Black Lotus、Mountain Silversage……", "グロッル……なんだと？\n\nYelmakがこの薬を、ほかの試薬なしでヤリクサとガマだけから作っただと？ 毎日見かけるこんなありふれた草が、錬金術師に本当に要るとは知らなかった。\n\nあいつの言うとおりかもしれんな。一番珍しくて研究の進んでいない植物にいきなり飛びつくせいで、見逃していることがたくさんあるのかもしれん。\n\n{name}、前に調合しておいたこの薬から、好きなものを一つ選んでくれ。わざわざ店に寄ってくれて感謝する。", 0xdbca40f0, 0xade06c15, 0xe2d2b0c3, 0x09c7d8d9, 0x71e92119, "....." },
  [97277] = { "GrundとGozwin", "北西の丘にあるGrundとGozwinのキャンプを見つけてください。Gozwin's Mechanic's Logを取り戻し、Snow Leopard Prowlerを倒してください。", "おい、猪の丸焼きの支度で背中を向けとったら、相棒のGozwinが命からがら叫ぶのが聞こえたんだ！\n\n振り向いた時に見えたのは、恐ろしい牙と、何かの影がさっと動くのだけだった。でっかい足だったぞ！ 雪豹がノームの獲物を引きずっていこうとしとったんだ。わしはショットガンをつかんで、獣の頭上に撃った。そしたら奴はあいつを放して走り去った。\n\n運のいいことに、Gozにはいくつか深い引っかき傷がついただけで済んだ。\n\n北西の丘にある野営地に戻って、Gozwin's Mechanic's Logを取ってきてくれ。あの雪豹を見かけたら、そいつも殺してくれ！", "かわいそうなGozは、自分の身よりメカウォーカーのほうが心配なんだよ。あの整備日誌を誰かに奪われたら一巻の終わりだってさ。ハッ！だから仕事は家に置いてこいって言ってやったのさ！", "ああ、あのユキヒョウがわしらの焼くつもりだった猪を餌にしてたと聞いても驚かんよ！\n\nお前さんが日誌を持ち帰ってくれたから、Gozも気に病むことが一つ減るだろう。これでやっと、立ち直ることに全力を注げるかもしれん。\n\nありがとうな、{name}。はるばる来てくれて、丘を守ってくれた感謝のしるしだ、ちょっとしたものを受け取ってくれ。", 0x13ae186f, 0xe97684ed, 0x403ef042, 0x3dbaa3c1, 0xab467190, "....." },
  [97279] = { "迷子の武器", "Abandoned Training Weaponを$N1個集め、DenにいるKzan Thornslashのところへ戻ってください。", "お前のような新兵がどっと入ってきたせいで、武器の供給が追いつかん。うちの武器鍛冶のKzanは訓練用の武器が不足しているし、俺はどんな手駒を相手にするのか知るために、お前がどんな技を持っているか見てみたい。運のいいことに、両方の問題を解決する手がある。\n\n外で猪を相手に腕を磨くついでに、捨てられた訓練用の武器を6つ回収してこい。落ちこぼれた新兵どもが地面に放り出していったものだ。済んだら、俺の後ろのDenにいる武器鍛冶のKzanに渡せ。", "Throm'ka、{class}。お前が来るとGorakから聞いていた。無事な姿が見られてよかった！\n\n頼んでおいた訓練用の武器は集められたか？", "武器を返してくれてありがとう、{name}。次の新兵たちのために修理に取りかかろう。", 0x85cc0347, 0x8f4e8fc9, 0x4b72157d, 0xe3abc6ea, 0x21e3c142, "....." },
  [97281] = { "くすぶる嵐", "Dull Stormy OrbをDrygulch Ravine付近にいるRezlakに届けてください。", "<目の前に、表面のくすんだ奇妙な球体がある。手に取ると、内側から小さな電流が震えるように伝わってくる。よく見ると、中で暗い霧が渦巻き、ときおり小さな電気の火花が見える。\n\nharpyが何かの目的でこれを使っていたのは明らかだ。Rezlakならこの物に興味を持つかもしれない。>", nil, "うわあ、そんなすごいものどこで見つけたんだい？ そういえば、ボスのGazloweがいつも言ってた別の話を思い出すな……", 0x1d3d3e08, 0xbc513c0b, 0x8130886a, nil, 0x703847de, "...m." },
  [97282] = { "嵐の潜在力", "Charged Thunder Lizard Organを$N1個、Drygulch Ravineの近くにいるRezlakのところへ持って行ってください。", "「Rezlack、チャンスが扉を叩いたら、つかみ取れるように準備しとけ」。これもGazloweに教わった名言のひとつさ。で、まさにそれをやるつもりなんだ。\n\nこのオーブは壊れてるようには見えない。単にエネルギー切れってだけだ。でも、こいつを過充電して元の力に戻すアイデアがあるんだ！\n\nここから西の峡谷に、thunder lizardがわんさといる。強い電気を蓄えた器官を持ってて、こいつにぴったりなんだ。\n\n何匹か狩って、その器官を持ってきてくれ！", "雷トカゲなんて名前なのに、雷みたいに吠えるんじゃなくて稲妻を放つってのは意外かもしれんな。\n\nいや、本当に放つんだ。稲妻をな。\n\n信じてくれ、運が良ければの話だが、一度しか学べない教訓だ。", "おお、ありがとな、相棒！ ここでは本当に大助かりだったよ、感謝してる。\n\nこの臓器で全部充電できるといいんだけどな。そうすりゃ、あのろくでもないharpiesも、俺のキャラバンをまた襲う前に考え直すだろうさ。うまくいくといいんだが。\n\nいずれにせよ、お前は取引の自分の分をきっちり果たしてくれた。手間賃にこれを受け取ってくれ。", 0xcc6ed58f, 0x1994e522, 0x12b14931, 0xaea78271, 0xe9dc28ef, "....." },
  [97284] = { "Vahlarrielの復讐", "DesolaceのThunder Axe FortressでBurning Bladeのオークを倒し、Nijel's PointのVahlarriel Demonslayerのもとへ戻る。", "Malemがまだ生きているなら、Burning Bladeのオークどもは、そのうち誰かが彼女を探しに来ると予想しているだろう。奴らは間違いなく戦う準備ができているはずだ。\n\nお前には目立たないようにして、奴らに近づかないでいてほしいところだが、実際には、奴らはあらゆる機会にお前を待ち構え、刃とBurning Bladeを交えようとしてくるだろう。\n\nだから、最初から戦果を数えておくことにしよう。できるだけ多く倒せ。そうすれば、その手間に見合うだけの礼はする。", nil, "よくやった。Thunder Axeの愚か者どもに対するお前の働きで、奴らも次に通りかかる隊商を襲う前に、きっと二の足を踏むだろう。\n\nうまくいけば、奴らは門の奥に縮こまったまま、勝手に滅びてくれるだろう。", 0x8067ec59, 0xf8a6125b, 0x9c85e944, nil, 0xebf88a96, "...m." },
  [97286] = { "研究資料の閲覧", nil, nil, nil, "あなたの行いは、あなたが知識を重んじる者であることを示しています。図書館は、あなたの研究のために開かれています。", 0xd0907e8d, nil, nil, nil, 0x0972665c, ".mmm." },
  [97287] = { "抜け目ない交渉", "Dalaranの近くにいるImage of Archmage Moderaと話してください。", "よくぞメイジの都市に潜り込んだ。だが、そろそろもっと……交渉的になる時だと思う。\n\n認めるのは癪だが、Azeroth広しといえども、これほど膨大な秘術の知識がある場所は他にない。私の輝かしい研究も、Kirin Torが長年かけて蓄えてきた古の英知と比べれば、まだ見劣りする。そろそろ我々もこの排他的な結社への出入りを許されていい頃だ。そう思わないか？\n\nお前が手に入れた欠片を持っていけ。奴らはそれを取り戻すためなら、きっと何でも差し出すだろう。何でもな。", nil, nil, 0xe4acb80b, 0x93700c3f, 0xb6c29c5f, nil, nil, "...mm" },
  [97288] = { "終わりなき苦悶", "Abominable HeadをUndercityにいるMaster Apothecary Faranellに届ける。", "<その生き物が倒れると、首が転がり落ちる。何度もつなぎ直されたようで、つなぎ直すたびに接合が弱くなっているらしい。\n\nUndercityの誰かなら、この珍しいabominationについてもっと知っているだろう。>", "おや、これは何だ？", "おお！この首には見覚えがあるぞ。Dark Ladyの残酷な冗談だ。しかも実に美味な冗談だ。\n\nこれには使い道がありそうだ。", 0x88dcf75e, 0x5d3272d3, 0x045ff381, 0x2b2c91f6, 0x3d028316, "....." },
  [97289] = { "終わりなき苦悶", "Head of the BaronをUndercityにあるOthmarの遺体のところへ持っていってください。", "我々はabominationの頭をしょっちゅう作っているが、こいつは特別だ。かつてはAllianceの大元帥のものだった。とりわけ不愉快な奴でな。名はOthmarだったと思う。Dark Lady自らが、こいつを始末する楽しみを味わわれたのだ。\n\nおお、こいつが口をきけたら、どれほどの秘密を語ることか。そして、きけるのだ！ふさわしい宿主に付け直してやればな。\n\nさあ、隣の部屋にある空いている体の横にこれを置いてこい。だが、付けるなよ。まだだ。", "<操る頭がなく、abominationは命なきまま動かない。>", "<死体がぴくりと動いて息を吹き返し、最期の瞬間を再び味わうかのように恐慌をきたす。>\n\nお前は……", 0x88dcf75e, 0x8392a5dc, 0x21af4dd7, 0x09afdccf, 0xf5efb3f9, "....." },
  [97290] = { "終わりなき苦悶", "UndercityのMaster Apothecary Faranellに調査結果を報告してください。", "貴様……abomination……\n\nなぜ……貴様を……助けねば……\n\n失せろ……", nil, "協力しないというのか？素晴らしい。私は挑戦がいつも大好きでね。", 0x88dcf75e, 0x76cbafb3, 0x0d26ec99, nil, 0xdfbc27f5, "...m." },
  [97291] = { "終わりなき苦悶", "UndercityのMaster Apothecary Faranellのために、Trade QuarterのTawny GrisetteからToxic Skullcapを、Herbalismのトレーナーの近くでBlisterweedを、Rogues' Quarterの毒商人からEssence of Agonyを集めてください。", "首はつなぎ直したので、あとはDark Ladyの意志に縛りつけるだけです。これは問題ないでしょう。これまで散々打ちのめされてきたせいで、あの獣にはもうほとんど脳みそが残っていませんからね。\n\nただ、やる気を出させてやればいいのです。\n\nTrade QuarterのMiss GrisetteからToxic Skullcapを取ってきてください。ああ、それと地元の薬草学のトレーナー、AlliestarsからBlisterweedも。遠慮なく持っていってかまいませんよ、私に借りがありますから。そして最後に、Essence of Agonyを少し。そこらの毒売りで十分です。\n\n作るべき薬があるのです！", "迷える子羊が群れに戻ってくるなんて、本当に素敵なことだと思わない？", "これなら申し分ない。我らが大切な客人が私の傑作を味わった後、どれだけ虚勢を保っていられるか見ものだな。", 0x88dcf75e, 0x3c831878, 0x10e94e21, 0xe35d5b4a, 0x7ba6274b, "....." },
  [97292] = { "終わりなき苦悶", "Master Apothecary Faranellのために、Othmarの遺体の上にある装置へHissing Serumを注入してください。", "新しいお客様がきっと……刺激的だと感じてくれる、素敵な血清を調合しましたよ。\n\nこれを持っていきなさい。彼の上から滴っている仕掛けに流し込むのです。忠実に仕えるのが彼自身のためだと、わからせてやれないか見てみましょう。\n\nそれと、落とさないように。新しい助手を雇う余裕はないのでね。", "Dark Ladyに背いたOthmarの罪を思えば、あの滲み出る標本の下に置いてやるのは、最低限の報いだ。\n\nそれに、面白いしな……", "素晴らしい。奴の肉はしばらく煮込んでおこう。新しい住まいに慣れる時間をくれてやるのだ。\n\n今のところあの哀れな奴にもう用はないが、目は離さずにおこう。Othmarの将来については、多くの計画があるのでな。", 0x88dcf75e, 0xcad79e1e, 0xfef7f8a7, 0x92d9ddce, 0x51def099, "....." },
  [97319] = { "異国のいとこ", "Mount Hyjalのどこかにいる、行方不明のいとこを見つけてください。", "Kalimdorにいる俺のいとこが、あっちで一番危険な場所を片っ端から切り抜けていて、最後に聞いた話じゃMount Hyjalへ向かってるらしい。\n\nまったくばかばかしい時間の無駄だと思うがな。\n\nもしあんたがあっちの方へ行くことがあったら、あいつがまだくたばってないと分かるとありがたい。今のところはな。", nil, nil, 0xad20a851, 0x71fdca5e, 0xcd946fa1, nil, nil, "...mm" },
  [97326] = { "岩を休息所に", "Smooth Boulderを$N1個、Grommash Holdの裏にいるThraのところへ持って行ってください。", "ねえ！手伝ってくれる時間あるでしょ！わかってるんだから。わたしたちが遊んでるゲームを見て、にっこりしてたもん。\n\nGrommash Holdの裏のこの場所は、駒を並べられるくらい開けてるからいいんだ。でも困ったことに、椅子やテーブルにする岩が足りないんだよ。\n\nあなたは大きくて力持ちだし……休みたいときに座れるくらいすべすべした、中くらいの大きさの岩を運んできてくれない？", "いつも土の上に座らなくて済むのはいいね！", "どうやってあの岩を全部運べたんだい！\n\nどれもすごくいいよ。ほとんどは平らな面もちゃんとある。君がここまで全部運んでくれたから、あとは土の上で好きな場所まで転がして動かせるね。\n\nありがとう、{name}！", 0xf790b060, 0xc71bf5e0, 0x831d0833, 0x1382164d, 0xc29549c2, "....." },
  [97327] = { "Blackmaw Pouches", "Blackmaw Holdに入り、AzsharaのRuins of EldarathにいるEkkalのためにBlackmaw Pouchesを$N1個回収する。", "認めるのはつらいが、Blackmaw Holdの中にいる兄弟姉妹たちは、もう元に戻れないほど堕落してしまった。\n\n彼らの持ち物をいくらか持ってきてくれれば、せめて家族に彼らを偲ぶよすがを渡してやれる。あなたが取り戻す包みのひとつひとつが、我が民へのあなたの奉仕の証となるだろう。", nil, nil, 0xe558c49d, 0x560604f0, 0x01e4835e, nil, nil, "...mm" },
  [97328] = { "価値ある物", "Stranglethorn ValeのRuins of Zul'KundaからStolen Shipmentsを$N1個取り戻し、その品をBooty Bayの誰かのもとへ持ち帰る。", "<真上で起きた悲惨な飛行船墜落事故が残した残骸を調べると、物資の大きな積荷の痕跡が見つかった。とうの昔に価値のあるものはすべて略奪されている。発送ラベルさえも引き裂かれ、ずたずたにされていて、そのうち一枚に「Booty Bay」という文字がかろうじて読めるだけだ。\n\n無数の二本指の足跡と、えぐられた地面のいくつもの跡が、すべて北西の遺跡へと続いている。>", nil, nil, 0xd56cd924, 0x19d4694d, 0xa7fe74f8, nil, nil, "...mm" },
  [97329] = { "鍵はどこ？", "Stranglethorn ValeのRuins of Zul'kundaにいるトロールから手に入れたPrimitive KeyをZimmix Sputtersparkに届ける。", "あんた！そう、あんただ！こっちに来てくれ、声を落として！\n\n大失敗しちまった。Booty Bayのために、あいつらの飛行船の塔を速達便に使えるうまい取引をまとめたんだが、最初の便で、でっかい鳥を見て……いや、すぐここの東で撃ち落とされたんだ！\n\n墜落からは、あいにく生き延びたんだが、目が覚める前にもう耳を引っ張られて引きずられてたんだ！今じゃ血に飢えたトロールに囲まれて、檻に閉じ込められてる！\n\nいいか、鍵さえあればいいんだ、な？自分で逃げられるから。", nil, nil, 0x4cd8cc0a, 0x11d8de27, 0x2fef21bb, nil, nil, "...mm" },
  [97331] = { "Zimmixの大脱走", "Zimmix SputtersparkをRuins of Zul'Kundaから護衛して連れ出し、Booty BayのWharfmaster Lozgilに救出の成功を伝える。", "待って、待ってくれ、まだ行かないでくれ！\n\n鍵さえあればいいって言ったけど……その、一度捕まったんだから、また捕まるかもしれないだろ？俺はたった一人のゴブリンで、この辺りには何百ものトロールがいるんだ！\n\nこの鍵を手に入れるまでに、もう奴らの数を十分減らしてくれたんだから、俺たちがのんびりここを抜け出す間、見張りに立つくらい簡単だろ？", nil, nil, 0x27ec33fb, 0x6aebab8a, 0xad346a39, nil, nil, "...mm" },
  [97332] = { "二度も見当違いの信頼", "Twice Reordered PackageをRivergladesのPowderfuse PortにいるWharfmaster Whizzbuzzに届ける。", "あいつのことは好きじゃないけど、Bloodscalp族が捕虜に何をするかは聞いてるし、ひどいもんだよ。Zimmixが無事に抜け出せてよかった。\n\nでもね、また急ぎの配達があって、あいつにそれを任せるなんて絶対に信用できない。問題は？あいつより先にこれを引き受けられる者が、ほかに誰もいないってことさ。その点、あんたは失くした積み荷と捕まったゴブリンを助け出してくれたから、こっちから見ればかなり信用できそうだ。\n\nこれをPowderfuse PortのWhizzbuzzのところへ届けてもらえないかな？", nil, nil, 0x01a0c8e6, 0x47bdbd9a, 0x3c8eb415, nil, nil, "...mm" },
  [97378] = { "Mirrorscale", "Mirrorscale's WingをThunder BluffにいるMelor Stonehoofのところへ持って行く。", "{name}、そなたは自らが強く忠実なハンターであることを示し、私はその勇気に感服している。だからこそ、この狩りをそなたに託すのだ。\n\nFeralasの沿岸を走る道で、一頭のwind serpentが狩りをしている。旅人たちを待ち伏せしては、その亡骸を道に散らかしているのだ。生きるために狩っているのではないことは明らかだ。もはやEarthmotherの祝福を分かち合わぬ生き物なのだ。\n\nwindserpentのMirrorscaleは、Feralasの海岸沿いにある滝の底を根城にしている。", nil, nil, 0x40644be3, 0x8b3be0d3, 0xebdb1247, nil, nil, "...mm" },
  [97386] = { "Grom'golの攻勢", "Mosh'Ogg Ogre Mountでogreを倒してほしいと、Grom'golのベースキャンプのCommander Aggro'goshは言っている。", "{name}！いつもながら、いい時に来てくれた。\n\nお前はGrom'golの防衛に大いに力を貸してくれた。感謝している。お前が先日、近くのogreどもを攻め立てた後、我々は斥候を送り、奴らの仲間が他にもいて我々に復讐しようとしていないか探らせた。案の定、はるか東に洞窟があって、奴らはそこをねぐらにしている。\n\n友を一人か二人集めて、我々の拠点への新たな脅威は、今もこれからも決して許さないと、はっきり思い知らせてやれ！", nil, nil, 0x58c910e7, 0x93dbc428, 0x7aba1639, nil, nil, "...mm" },
  [97403] = { "双頭の破壊者", "Chillwind Ravagersを$N1体倒し、Winterspring北部のRilan Howardのもとへ戻る。", "このキメラどもは残酷な冗談のようなものだ。舌が2つ、どちらも汚らわしく、冷気と飢えを唸り散らす。まるでこの荒れ地にまだ牙が足りないとでも言うようにな。\n\nこの空き地が我々のすべてだ。腰を落ち着ける前に、いつも嵐に飲み込まれてしまう。双頭のChillwind Ravagersが我々の周りを回り、決意を試し、時間を削り取っていく。\n\n何か価値あるものを築くより、奴らを追い払うことに多くの時間を費やしている。\n\n奴らを間引いてくれ。ここでの奴らの存在を打ち砕くのだ。うろつく獣が減れば、この凍った荒れ地から、まだ何か長く残るものを切り出せるかもしれん。", nil, nil, 0x3ee999fd, 0x07399a0e, 0xda11bfa6, nil, nil, "...mm" },
  [97404] = { "耐え難き熊", "年老いたshardtoothの群れの長、KuromaとKamuroを倒し、その首をSarna Brownhornのもとへ持ち帰る。", "年老いた2頭の母熊がいる。子育ての時期などとうに過ぎた年寄りだ。姉妹なのかもしれん。あるいは、似たような季節の移ろいを共にしてきた、気の合う2頭の熊なのかもしれん。\n\n何が奴らを結びつけたにせよ、奴らにはまだ敬意を払うべき獰猛さと生きる意志がある。ここにこのような野営地を築こうとするのは、この白髪交じりの2頭のShardtoothsのせいで骨が折れた。\n\nKuromaとKamuroの首を持ち帰ってくれ。できる限り素早く、巧みに、そして慈悲をもって終わらせてやってくれ。", nil, nil, 0x9266c688, 0xa0d7ef41, 0x45090772, nil, nil, "...mm" },
  [97405] = { "騒音の苦情", "Mosh'Ogg Ogre MountでMosh'Ogg Spellcrafterを$N1体、Mosh'Ogg Warmongerを$N2体、Mosh'Ogg Maulerを$N3体、Mosh'Ogg Shamanを$N4体倒してほしいとKnaz Blunderflameは言っている。", "あっちのGnazは、はるばるKalimdorである大会のために、あの死の罠みたいな代物を作ってるんだ。毎晩夜遅くまでいじくり回してるせいでものすごい音がしてるって、ずっと注意してたんだけど、昨夜、あの木の陰からogreが醜い頭をのぞかせてるのを見ちゃったんだよ！\n\nあいつはMirage Raceway Championshipsで優勝するっていう大それた夢に夢中だけど、こっちは八つ裂きにされないことに夢中なんだ！北の丘を越えていって、あいつらがこのへんを嗅ぎ回るのをやめさせてくれよ。", nil, nil, 0xf5dba294, 0x634f040e, 0x4f39b5e6, nil, nil, "...mm" },
  [97411] = { "真剣な申し出", "Silithus Venom Samplesを15個と20ゴールドを用意し、Lightforge Bracers一式と一緒にOrgrimmarのMokvarのもとへ持っていく。", "やあ、{class}！その物腰を見れば、あなたがこの世界で多くを見て、多くを成し遂げてきたことがわかります。それでも、このような防具はまだ見たことがないと賭けてもいいでしょう。\n\nちょっとした頼みを聞いてくれれば、普通のブレイサー一式と交換でこれを譲ってもいいですよ。\n\nSilithusに棲むクモやサソリから採った毒のサンプルがたっぷり必要なのです。それを数枚の金貨と一緒に持ってきてくれれば、交換いたしましょう。", nil, nil, 0x5744ae45, 0x30ac6ac9, 0xea675b9d, nil, nil, "...mm" },
  [97420] = { "減らして、使い回して、丸く収めて", "Lake NazferitiのVenture Co.の作業場からDrums of Crude Oilを$N1個手に入れ、Stranglethorn ValeのKnaz Blunderflameのもとへ戻ってください。", "誰かに頼みたいことがあるんだけど、君は頼りになりそうだね！\r\n\nこいつが見えるかい？きれいだろ？僕の最新のレーサーさ。「誰かさん」が手伝ってくれなかったから、設計も組み立ても全部ひとりでやったんだ。Thousand Needlesのレースに出すつもりなんだけど、もうひと押しのパワーが足りないんだよ。\r\n\nさて、僕はゴブリンなんかじゃない、ゴブリンにしてはハンサムすぎるからね。あいつらの技術を信用しちゃいけないことも分かってる。でも、Venture Coが向こうの湖で液体の金を掘り当てたのは知ってるんだ。君がちょっと、その、借りてきても、きっと気にしないさ。気づきもしないよ！", nil, nil, 0x4056755c, 0xc361c56c, 0x4d212a67, nil, nil, "...mm" },
  [97446] = { "初めての騎乗用Kodo", "騎乗用のkodosを見て回り、最初の騎乗動物を選ぶ。", "ああ、待っていたぞ、{class}。今日は風がお前を私のもとへ運んできたようだな。kodoを求めて来たのだろう？\n\nkodoは高貴な獣で、めったに怒らない。これほど頼りになる相棒は、なかなか見つからないだろう。\n\n今日、お前には大事な選択がある。お前とkodoは共に世界を旅することになる。だから、どのkodoがお前に語りかけるか見つけるのだ。案ずるな、どれを選んでも、それが正しい選択だ。\n\nkodosを見て、選んだら私のところへ戻ってきなさい。", nil, nil, 0x2f8c7c80, 0x9ca0fd73, 0xa07cac2b, nil, nil, "...mm" },
  [97447] = { "真剣な申し出", "Winterspring Blood Samplesを15個と20ゴールドを用意し、Bindings of the Elements一式と一緒にIronforgeのDelianaのもとへ持っていく。", "ごきげんよう、{class}。あなたが興味を持ちそうなものがあります。\n\n私の手元に、あなたと同じ職業の者が身につけるものによく似た、しかしはるかに上質な防具一式があります。ちょっとした頼みを聞いていただければ、そのブレイサーを普通のものと交換してさしあげましょう。\n\nWinterspringに棲むfrostsabersや熊の血には、今の私が必要としている性質があります。その血のサンプルをたっぷりと、ブレイサーと少しのゴールドと一緒に持ってきてください。その苦労に見合う価値はあるはずですよ。", nil, nil, 0x5744ae45, 0x9407c1a6, 0x9df430b9, nil, nil, "...mm" },
  [97453] = { "雑草退治", "Grom'golの南でCarnivorous Weedを$N1体倒し、Gemmilの母親に知らせる。", "ねえ、手伝ってくれる？\n\nパパとママがやっとこの大きなジャングルに連れてきてくれて、門のすぐ外で草を少し摘んでもいいって言ってくれたの。いつか錬金術師になれるように、薬草学を勉強してるんだ！\n\nそれでね、リュックがもうちょっとでいっぱいになるところで、大きくて怒った雑草がどこからともなくたくさん出てきて、私につばを吐きかけてきたの！\n\n逃げたから大丈夫なんだけど、もうキャンプの外で遊んじゃだめって言われちゃった。安全にしてくれたら、ママに伝えてくれる？", nil, nil, 0xc436e8d8, 0x3f3064d7, 0x6bfd1ba8, nil, nil, "...mm" },
  [97485] = { "Bluffの伝統", "薬草商NidaからBundle of Herbsを、付呪用品商NataからBundle of Cedar Twigsを、革細工用品商MahuからSinew Threadを、料理用品商NaalからCeremonial Flint and Tinderを購入して下さい。\n\nそれらを組み合わせ、Hunter's Riseから香を撒いて下さい。", "An'sheの祝福を、友よ。\n\n私たちトーレンには、お香を風に撒くという伝統があります。あなたがこの伝統を敬うことに関心を持ってくれればと思っていたのです。\n\nお香を作るには、Nidaから薬草を、Nataから杉を、中段にいるMahuからsinew threadを、上段にいるNaalからceremonial flint and tinderを買う必要があります。これらがそろったら、混ぜ合わせて、Hunter's Riseの南向きの崖から撒いてください。\n\n儀式の場所には敷物とお香があります。", "香を風に乗せる機会はたくさんあります。誰かを見守ってくれるようEarthmotherに願うことも、狩りの祝福や何かのお祝い、さらには祖先に導きを求めることもあるでしょう。\n\nあるいは、まったく別の何かかもしれません。\n\nこの行いは敬意をもってなされますが、厳密には儀式というわけではありません。この行いをするときには、たいてい決まった伝統的な手順が守られますが、多くの部族ではやり方が異なります。", "よくやってくれました。\n\n我らの古くからの伝統の一つを行うために時間を割いてくれたことに感謝します、skyborne。旅の中で、感謝を捧げたいと思える機会にたくさん出会えますように。\n\nもう一度この儀式を行いたいときは、集めてくるよう頼んだ材料をまた買うことができるはずです。\n\nAn'sheの温もりと共に行きなさい。", 0x8de39461, 0x5aef4be7, 0xd944b43a, 0xb3960157, 0x837694f1, "....." },
  [97490] = { "雹を止めよ", "Winterspringの南の丘でHailspiteという巨人を探し、その体に生えている霜の苔を回収する。", "よう、あんた。部品を取るためにガラクタをばらしてるんだが、どうにも熱くなりすぎちまってな。\n\n言いたいことは分かるぜ。Winterspringで？熱くなる？見てのとおり、俺の粉砕機とreployerは動いちゃいるが、ひどくガタガタ咳き込んでる！本当に必要なのは、溶けたり、滑ったり、燃え尽きたりしないで冷やしてくれる何かなんだ。\n\n南の丘に、俺たちがHailspiteって呼んでるたちの悪い巨人がうろついてる。Hailspiteを始末して、そいつの岩肌に生えてる霜の苔を持ってきてくれ。\n\nうまくいくかもしれねえ！", nil, nil, 0xe393571a, 0x63f1f929, 0x5040f785, nil, nil, "...mm" },
  [97530] = { "Dunemaulへの報い", "Dunemaulのogreの集落近くで失くされた、特にピカピカのバングルを取り戻してほしいと、TanarisのSteamwheedle PortのSecurity Chief Bilgewhizzleは言っている。", "商人の隊商が砂漠で道を間違えて、Dunemaulのogreどもに襲われたんだ。生きて逃げ出せたのは、あの獣どもの気をそらすために積み荷を少し放り出したからってだけさ。\n\nどうやらその商人は船や飛行船を動かしてるお偉方とつながりがあるらしくてね、今度はこの「俺」に、なくした物を拾ってこいってさ。\n\n俺はここで仕事に縛られてる。でも、「あんた」がogreどもをぶちのめしてる間に、きれいでピカピカの腕輪を見つけたら、それなりの礼はするよ。", nil, nil, 0x38753845, 0xbddf478b, 0x7e7d1117, nil, nil, "...mm" },
  [97534] = { "砂だらけの仕事", "Desert Debrisを$N1個回収して、Gadgetzanにいる自分のところへ戻ってきてほしいとQuinnは言っている。", "なあ、いいこと教えてやろうか？こういう場所じゃ、思ってるより簡単に儲けが出せるんだ……要は売り方を知ってるかどうかさ！ここの技術オタクどもが、燃料電池にできそうな物を手に入れたらどうするか、俺はこの目で見てきたんだ。\n\nまだ光ってたり、蒸気を噴いてたりしたら、なおさらいい。\n\nひとつ取引しないか？砂漠で奴らの機械から落ちた部品を持ってきてくれたら、そのがらくたをジャンク屋に売りつけて手に入れた金の分け前を、お前にも回してやるよ！", nil, nil, 0x458c5266, 0x469a7416, 0xe621a6b5, nil, nil, "...mm" },
  [97536] = { "ノームのゴミ", "Crate of Radioactive RefuseをGadgetzanや他のゴミから安全な距離だけ離れたTanarisの砂漠に捨ててから、自分のところへ戻ってきてほしいとJhordy Lapforgeは言っている。", "Matter Transporterをちゃんと動かすには実験が必要だった。ありとあらゆる素材で何度も試験をしたんだ……結果はいろいろさ！もうこの世にない結果もある。危険なほど帯電しちまったものもある！\n\n実験台になったこいつらは、近くに長くいすぎると火傷するエネルギーを放ってる。まるで砂漠の太陽の力を一年分たっぷり浴びせられたみたいにな。\n\nこのCrate of Radioactive Refuseを持っていって、町やほかのゴミから安全な距離を取った砂地に中身を空けてきてくれ。", nil, nil, 0xc60ec55d, 0x53ea08c2, 0xad44b91a, nil, nil, "...mm" },
  [97538] = { "絵の具のための顔料", "Thunder BluffにいるTah Winterhoofは、Mirkfallon LakeのMirkweed Podsを$N1個ほしがっています。", "ごきげんよう、友よ。ひとつお願いをしてもよいでしょうか？ 絵の具の赤い顔料がちょうど切れてしまって、私の代わりにStonetalon Mountainsへの長い旅をしてくれる、若い蹄の持ち主を探しているのです。\n\n山道の真ん中に、Mirkfallon Lakeという大きな丸い湖があり、その水の中に珍しい植物が育っています。この植物、mirkweedのさやは、乾かすと鮮やかな赤になるのです。この植物のさやを集めてきてくれれば、その働きに十分報いましょう。", "戻ったのですね！Mirkfallon Lakeでmirkweed plant podsは見つかりましたか？\n\n我々トーレンは何世代にもわたって、この植物の色素を絵の具に使ってきました。ですから、どれだけの量でも持ってきてもらえればありがたいのです。赤い色素を得る方法はたくさんありますが、私の知る方法の中では、mirkweedが最も豊かで鮮やかな色合いを出すと思います。", nil, 0xaa3850ee, 0x98b0df48, 0xd373bd5c, 0x3ae2b31d, nil, "....m" },
  [97539] = { "絹の縫合糸", "Arathi HighlandsのHammerfallにいるDoctor Gregory VictorにSurgical Spidersilkを12個届けて下さい。", "この野営地は朽ちるに任されている。攻城戦の損傷はそのまま放置され、まるで怠慢が方針であるかのようだ。ここで同じ荒廃を許すつもりはない。診療所は私の管轄で、機能させ続けるつもりだ。\n\n物資はほぼ底をついている。作業員と衛兵を立たせておくだけの備品が、もっと必要になる。\n\n切迫した状況なら、撚ったクモの糸でかなり効果的な野戦用の縫合糸が作れる。\n\n{class}、この高地をうろつくクモから糸を取ってきてくれ。", nil, nil, 0xdf5a915e, 0x4b00338c, 0x5c3dc6d2, nil, nil, "...mm" },
  [97540] = { "オアシス", "喉の渇きが癒えたばかりのToogaを、妻のTortaのところまで案内する。", "ああ、このきれいな水、なんていい匂い……\n\nちょっと立ち止まって、ひと泳ぎして水を飲んでいくね。", nil, nil, 0x77d8fe0c, 0xec717c40, 0xf2469823, nil, nil, "...mm" },
  [97558] = { "Forsakenのための皮", "Shelene RhobartにDuskbat Wing Membraneを$N1枚、Darkhound Hideを$N2枚、Vile Fin Murloc Skinを$N3枚持って行ってください。", "アンデッドになるということの、誰も口にしない一面がある。傷を負った時にどうなるかだ。アンデッドの皮膚はどうやって治るのか？\n\nさて、治らないのだ。\n\n我々の生は呪われている、{name}。自らの存在を続けるために、生者から奪わねばならない。\n\n傷を負ったら、皮膚を取り替えねばならない。たいていは動物の皮でだ。体の場所によって向いている皮の厚さが違うから、いろいろそろえておくのが肝心なのだ！\n\nduskbatの翼の膜と、darkhoundの皮と、Vile Fin murlocの皮膚を持ってきてくれ。", "頼んでおいた皮は集まったか？在庫が減ってきているのだ。\n\nmurlocの皮を求めるのは妙に思えるかもしれんが、内側の膜や、頬や口のような面には実によく合う。\n\n同じように、duskbatの翼の膜は、顔や指といった、より繊細な部分に特に向いている。皮が……厚くなりすぎるのを防いでくれるのだ。", "ああ、素晴らしい！これを手に入れてくれてありがとう。きっと役立てると約束しますよ。", 0x09dcf31d, 0x19613344, 0x932d29f0, 0x6d509c4e, 0x35944081, "....." },
  [97583] = { "WRIGGLE.", "Nutritious Slime Sludgeを購入し、仲良くなった元気なスライムのところへ戻って下さい。疲れているようなら、もう一度一緒に踊って気を引いてみて下さい。", "<小さなスライムは嬉しそうで、あなたが踊るとその動きを真似ようとしている。だが、疲れてきたようだ。\n\n小さなスライムは少しの汚泥の上に浮かび、それを吸収して、わずかに元気を取り戻したように見える。\n\nこれだけ踊って、すっかりくたびれてしまったらしい。Undercityの運河にいる誰かが、この栄養たっぷりの汚泥をもっと売っているのではないだろうか？>", nil, nil, 0x196f6916, 0x0ed19c12, 0x943783d3, nil, nil, "...mm" },
  [97617] = { "安全点検", "Unstudied Artifactを$N1個、Explorers' League Mining Helmet、Pristine Mattockを回収し、Loch ModanとBadlandsの境にいるDorgaronのところへ持って行く。", "よう、お前さん、頼りになりそうな顔をしとるな。\n\nわしはDorgaron、Explorers' Leagueの者だ。Badlandsでの発掘はどうもうまくいっとらんが、見つけて集めるべき遺物がまだあるのは百も承知だ！\n\n親方を説得してここへもう一組送り込ませるには、発掘現場が安全で、しかも掘り尽くされとらんことを証明せにゃならん。\n\n南へ行くことがあったら、そこそこ無傷の遺物をいくつかと、まだ壊されとらん残りの装備を集めてきてくれ。", nil, nil, 0xa657373f, 0x42920691, 0xff6fff61, nil, nil, "...mm" },
  [97663] = { "物資と研究", "Dustbowlでogreを倒してMus'hale's Stolen Suppliesを手に入れ、それを使って近くの石の彫刻の拓本を取る。その後、KargathにいるMus'haleのところへ戻る。", "Dustbowlで、変わった様子の岩がいくつか目に留まった。よく調べてみると、彫り物があったのだ！後で研究するために、拓本を取らずにはいられなかった。\n\n近くのogreどもが私に気づき、身構える間もなく、気がつけば宿屋の主人の介抱を受けていた。ひどい頭痛と一緒にな。\n\n今、私は道具をすべて失い、傷が癒えるまで研究の材料も何もない。東へ赴いて私の荷物を探し、君自身で彫り物の拓本を取ってきてくれないか？", nil, nil, 0x3dd5012d, 0x055fbd2d, 0xf1936994, nil, nil, "...mm" },
  [97821] = { "Mirage Mirror", "この発見に興味を持ちそうな人物をBadlandsで探す。", "<エレメンタルが倒れると、その核から遺物がひとつ落ち、砂の中できらめいた。\n\n手の中で傾けると、周囲の景色が映り込んで、あなた自身の目からそれを隠してしまった。映り込みを歪めるひび割れた面が見えた時、ようやくそれは再びはっきりと見えるようになった。\n\nこの発見に興味を持つ者がいるかもしれない。>", nil, nil, 0x6847d38a, 0x08baf57e, 0x57aa5b31, nil, nil, "...mm" },
  [97883] = { "Dark Hordeの終焉", "Head of Rend BlackhandをStormwindのMajor Mattinglyのもとへ持っていく。", "Blackhandの首を、城門にいるMajor Mattinglyのところへ持っていけ。彼と部下たちが、君が今日成し遂げた大勝利を宣言してくれるだろう。そうすれば、Allianceの他の者たちもそれに奮い立つはずだ。\n\n君は今日、偉大な正義を果たしたのだ、{name}。皆が覚えておくことになるだろう。我らの敵でさえもな。", nil, nil, 0x3409b38a, 0xc68501b7, 0x1e336650, nil, nil, "...mm" },
  [97884] = { "Sunnygladeの武器庫", "RivergladesのSunnygladeへ赴き、Tremayne Family Blacksmithing Techniquesの書物を取り戻す。", "君は健康で、体の丈夫な{race}のようだな。Redridge Mountainsのすぐ北、RivergladesにあるSunnygladeまで行ってくれる者を探しているのだ。\n\nかつて、私の家族はそこで武具店を営んでいた。今では焼け落ちた残骸になっているだろうが、我が家に代々伝わる鎧作りの技法を記した書物を取ってきてほしい。元は地下室に置いてあったから、まだ風雨にやられていなければよいのだが。", nil, nil, 0xdb50c496, 0x3df7946f, 0xb9bb6bfc, nil, nil, "...mm" },
  [97891] = { "迅速なポーション配達人", "制限時間内に、Unstable PotionをApothecariumのDoctor Martin Felbenに届けてください。", "そこのあなた！ 急いで、この薬を粘液の運河の向こう、ApothecariumのDoctor Martin Felbenのところへ届けてちょうだい！\n\nとても日持ちが悪いの。それと、いいえ、自分では行けないのよ。走ろうとすると膝がカタカタ鳴って外れちゃうんだから。\n\nどうやら、これもアンデッドになったことの素敵な副作用みたいね。\n\nでも時間の無駄だわ！ ほら、これを持って行って！\n\n<Alessandroはしっしっと追い払う仕草をする。>", nil, "ああ、見事だ！Alessandroの薬が届くのを待っていたのだ。前の6本は途中で不安定になってしまったが、お前は間に合わせてくれた！\n\nほら、骨折りの礼にこれを取っておけ。今はこれで全部だ。他に私に用があるなら別だがな。\n\nないなら、立ち去ってくれ。私の実験の邪魔をしないようにな。", 0x5ecd7075, 0x57e062c5, 0x38a757cf, nil, 0xad4dc35c, "...m." },
  [97894] = { "Auberdineでの商談", "DarkshoreのAuberdineにいるGorbold Steelhandの様子を見に行ってください。\n\nBorgusによると、Stormwind Harborの一番南の桟橋に、そこへ行ける船があるそうです。", "お近づきになれて嬉しいぜ！ わしの名はBorgus、あの唯一無二のSteelhand一家の者よ。公正な取引なら、いつだってSteelhandに任せときな！\n\n何週間か前、兄弟のGorboldがAuberdineの商人の露店に加わったんだ。あそこじゃ船に物資を納めて、たんまり稼げるんだぜ！ うらやましい奴さ。\n\nそれっきり音沙汰がなくてな。そっちへ向かうなら、ちょいと様子を見てきてくれんか？\n\n港に新しい船が来ていて、そこまで直行してくれる。一番南の桟橋へ行きな。見逃しっこないぜ！", nil, "Borgy老人がお前をよこしたのか？いつも俺のことを気にかけてくれるな。\n\nここではもう一人手が欲しかったところだ。最近の悲劇で商売はほとんど止まっちまってな。お前なら事態を立て直す助けになると思う。", 0x05e986b2, 0xc51e34fa, 0x4f88604b, nil, 0xe4fd9705, "...m." },
  [97899] = { "キャンプ101：Alchemy", "スキルの熟練を示したら、OrgrimmarのWhuutと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "で、錬金術師として酒や薬をこしらえる道を選んだってわけか。きっと旅で役に立つだろうよ。\n\n野営地用のMana Wellの作り方を教えてくれる奴を知ってるよ。こいつを建てれば、治療師や呪文使いの連中がみんな、爽やかな一杯を味わいに駆けつけてくるさ。", nil, nil, 0x32f4ba12, 0xc1f8026d, 0xf6c52c29, nil, nil, "...mm" },
  [97900] = { "キャンプ101：Blacksmithing", "スキルの熟練を示したら、Razor HillのDwukkと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "で、鍛冶屋になったんだって？ 刃を決して鈍らせたくないなら、いい選択だよ。\n\nSharpening Wheelの作り方を教えて、その手助けをしてくれる奴を知ってるよ。野営地でこいつを出せば、そのあたりのウォリアーやローグがみんな、武器を研ぎに列を作るだろうさ。", nil, nil, 0x16979ea3, 0xc5732bbb, 0x469a706e, nil, nil, "...mm" },
  [97901] = { "キャンプ101：Enchanting", "スキルの熟練を示したら、OrgrimmarのJhagと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "エンチャンターはなんでもより良くしてくれるし、荒野の野営地ならどこでも歓迎されるもんだ。\n\n野営地用のEnchanted Luteの作り方を教えてくれる奴を知ってるよ。暇な時間に楽しみを見つけるのはすごく大事なことでね、この魔法の品があれば、またほこりっぽい旅路に出た時、どんな困難にも耐えられるようにしてくれるさ。", nil, nil, 0x2e9b8c15, 0xd5fb1529, 0xb4a29ffc, nil, nil, "...mm" },
  [97902] = { "キャンプ101：Engineering", "スキルの熟練を示したら、Razor HillのMukdrakと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "あんたみたいなエンジニアは、面白半分にも儲けのためにも、あらゆる部品やボットや爆弾をこしらえられるんだよな。\n\n野営地用のReagent Botの作り方を教えてくれる奴を知ってるよ。この便利な自動人形が物資を切らさないようにしてくれるから、あんたも仲間も、呪文の燃料になる材料を切らすことはなくなるさ。", nil, nil, 0x1cb4025b, 0xcf977e31, 0x549b28c0, nil, nil, "...mm" },
  [97903] = { "キャンプ101：First Aid", "スキルの熟練を示したら、Razor HillのRawrkと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "First Aidを始めたって？ {class}としては、立派で……しかも実用的な道だね。\n\n野営地用のFirst Aid Kitの作り方を教えてくれる奴を知ってるよ。冒険の世界じゃ怪我はつきものだし、野営地で必要な治療を施してやれば、命を救うことにだってなるかもしれない。", nil, "ほら、これで自分だけのFirst Aid Kitを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0x6e7c255b, 0xa11a2e39, 0x32ff3188, nil, 0x3a282524, "...m." },
  [97904] = { "キャンプ101：Fishing", "スキルの熟練を示したら、Sen'jin Village付近にいるLau'Tikiと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "そうは思わないかもしれないが、釣り人としての腕は野営地で案外役に立つんだ。\n\n野営地用のFish Bowlの作り方を教えてくれる奴を知ってるよ。こいつを置けば、あんたや仲間の冒険者たちにちょっとした楽しみを与えられる。楽しい冒険者は強い冒険者だし、きっと戦いぶりにもそれが表れるさ。", nil, nil, 0xe0c1c700, 0x7cb6468b, 0x1bcf05fd, nil, nil, "...mm" },
  [97905] = { "キャンプ101：Herbalism", "スキルの熟練を示したら、OrgrimmarのJandiと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "どうやら薬草学の腕が少し上がったみたいだね。花摘みはただの暇つぶしじゃないんだよ。役にも立つし……儲かりもする。\n\n野営地用のIncense Candleの作り方を教えてくれる奴を知ってるよ。治療師や呪文使いを戦いに踏みとどまらせるには、士気の高さが肝心だ。Incense Candleがあれば、魔法使いたちがきっと喜ぶような後押しになるさ。", nil, "ほらよ、これでIncense Candleを自分で作れるようになったぜ。町のど真ん中にキャンプを張られるのを好む奴はあんまりいねえから、試してみたきゃ荒野へ出なきゃなんねえ。\n\nなあ、焚き火のねえキャンプは完全とは言えねえぜ。キャンプを始める前に焚き火がいるぜ。たいていの料理人が火の起こし方を教えてくれる。まだ基本を覚えてねえなら、料理の技術を教えてくれる奴のとこへ行ってみな。", 0xd7cde71c, 0xdecd7cd7, 0xe0048777, nil, 0x37424fd5, "...m." },
  [97906] = { "キャンプ101：Leatherworking", "スキルの熟練を示したら、OrgrimmarのKarolekと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "革細工師になったんだってな。いいことだ、{class}。暑い日には涼しく、雨の日には濡れないテントの作り方を教えてくれる奴を知ってるよ。\n\n頭の上にいいテントがあれば、旅のあいだも頭を冴えさせておくのに必要な休息をしっかり取れるってわけさ。", nil, nil, 0x40d05936, 0x78212a11, 0x86e620e9, nil, nil, "...mm" },
  [97907] = { "キャンプ101：Mining", "スキルの熟練を示したら、Razor HillのKrunnと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "Miningは一番華やかな仕事じゃないが、まっとうな良い仕事だし、試してみるにはいい職業だよ。\n\n野営地用のLodestoneの作り方を教えてくれる奴を知ってるよ。こいつを建てれば、剣を振るいたい連中がみんな、あんたの焚き火の周りに喜んで集まってきて、戦闘の腕を上げる「ひと押し」をたっぷり浴びていくだろうさ。", nil, "さあ、これで自分のLodestoneを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完成とは言えない。キャンプを始める前に焚き火が一つ要る。たいていの料理人なら火のおこし方を教えてくれる。まだなら、料理の技を教えられる者を訪ねて、基本を学んでおくといい。", 0xa8fe12f3, 0x7978666b, 0x8ef0fff6, nil, 0x0b8098cd, "...m." },
  [97908] = { "キャンプ101：Skinning", "スキルの熟練を示したら、OrgrimmarのThuwdと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "倒れた獣から皮をうまく剥ぎ取れるってのは、冒険者が持てる中でもかなり価値のある技なんだ。\n\n野営地用のCamp Chairの作り方を教えてくれる奴を知ってるよ。ときには腰を下ろしてひと休みするのも大事でね、集めた皮を使えば、座り心地のいい椅子が作れる。少しくつろげば、最高の調子を保てるし、次に揉め事に巻き込まれた時には、ここぞというところで一撃を加えられるってもんだ。", nil, "ほら、これで自分だけのCamp Chairを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0x14236b38, 0xd889c883, 0x1755b1ba, nil, 0x98c24a76, "...m." },
  [97914] = { "視野を広げて", "Thundris' LetterをStormwindのBaros Alexstonに届けてください。\n\nThundrisによると、Auberdineにそこへ行ける船があるそうです。", "Auberdineはつつましい場所です、{class}。Darnassusの枝々の間で、その名が語られることはないでしょう。たいていの者が口にするのは、Sunderingが私たちから奪ったものだけです。栄えた都市Ameth'Aran、Bashal'Aran、そして……Lathar'Lazal。\n\nそれでもAuberdineは、それらの影に取り残されたままです。\n\n私はここでの私たちの働きが認められるのを見たいのです。新しい船がStormwindの王国と私たちを結び、この岸辺に活気と物資をもたらしています。どうか次の航海に加わり、この手紙をBaros Alexstonという人間に届けてください。\n\n私たちの故郷を世に知らしめてください。", "海のにおいがするぞ、友よ！\n\n<Barosは笑った。>\n\n何の用でStormwindへ来たんだ？", "<Barosは手紙を開いて読み始めた。その笑みが消えていく。>", 0x47bf47e5, 0xe531658d, 0x0d17a10a, 0xccc0bbea, 0x30ab094d, "....." },
  [97915] = { "キャンプ101：Alchemy", "スキルの熟練を示したら、Stormwind付近のElwynn ForestにいるAlchemist Malloryと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "で、錬金術師として酒や薬をこしらえる道を選んだってわけか。きっと旅で役に立つだろうよ。\n\n野営地用のMana Wellの作り方を教えてくれる奴を知ってるよ。こいつを建てれば、治療師や呪文使いの連中がみんな、爽やかな一杯を味わいに駆けつけてくるさ。", nil, nil, 0x32f4ba12, 0x7a5b40ad, 0xf6c52c29, nil, nil, "...mm" },
  [97916] = { "キャンプ101：Blacksmithing", "スキルの熟練を示したら、GoldshireのSmith Argusと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "で、鍛冶屋になったんだって？ 刃を決して鈍らせたくないなら、いい選択だよ。\n\nSharpening Wheelの作り方を教えて、その手助けをしてくれる奴を知ってるよ。野営地でこいつを出せば、そのあたりのウォリアーやローグがみんな、武器を研ぎに列を作るだろうさ。", nil, "ほら、これで自分だけのSharpening Wheelを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0x16979ea3, 0xbc0dd4f8, 0x469a706e, nil, 0xe5c38af5, "...m." },
  [97917] = { "キャンプ101：Enchanting", "スキルの熟練を示したら、StormwindのBetty Quinと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "エンチャンターはなんでもより良くしてくれるし、荒野の野営地ならどこでも歓迎されるもんだ。\n\n野営地用のEnchanted Luteの作り方を教えてくれる奴を知ってるよ。暇な時間に楽しみを見つけるのはすごく大事なことでね、この魔法の品があれば、またほこりっぽい旅路に出た時、どんな困難にも耐えられるようにしてくれるさ。", nil, "さあ、これで君も自分だけのEnchanted Luteを作れるようになった。町の真ん中に野営地を張られるのを好む者はあまりいないから、試してみたいなら荒野へ出かける必要があるよ。\n\nああ、それと覚えておいてくれ。焚き火のない野営地は完成とは言えない。野営地を始める前に、焚き火がひとつ必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる人のところへ行って、基本を学んでおくといい。", 0x2e9b8c15, 0x1d55369b, 0xb4a29ffc, nil, 0x181203c3, "...m." },
  [97918] = { "キャンプ101：Engineering", "スキルの熟練を示したら、StormwindのSprite Jumpsprocketと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "あんたみたいなエンジニアは、面白半分にも儲けのためにも、あらゆる部品やボットや爆弾をこしらえられるんだよな。\n\n野営地用のReagent Botの作り方を教えてくれる奴を知ってるよ。この便利な自動人形が物資を切らさないようにしてくれるから、あんたも仲間も、呪文の燃料になる材料を切らすことはなくなるさ。", nil, nil, 0x1cb4025b, 0xba6c8a24, 0x549b28c0, nil, nil, "...mm" },
  [97919] = { "キャンプ101：First Aid", "スキルの熟練を示したら、GoldshireのMichelle Belleと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "First Aidを始めたって？ {class}としては、立派で……しかも実用的な道だね。\n\n野営地用のFirst Aid Kitの作り方を教えてくれる奴を知ってるよ。冒険の世界じゃ怪我はつきものだし、野営地で必要な治療を施してやれば、命を救うことにだってなるかもしれない。", "専門技能の腕を少し上げたら、教えてあげよう。", "ほら、これで自分だけのFirst Aid Kitを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0x6e7c255b, 0x872ca64f, 0x32ff3188, 0x558c53ee, 0x3a282524, "....." },
  [97920] = { "キャンプ101：Fishing", "スキルの熟練を示したら、Goldshire付近にいるLee Brownと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "そうは思わないかもしれないが、釣り人としての腕は野営地で案外役に立つんだ。\n\n野営地用のFish Bowlの作り方を教えてくれる奴を知ってるよ。こいつを置けば、あんたや仲間の冒険者たちにちょっとした楽しみを与えられる。楽しい冒険者は強い冒険者だし、きっと戦いぶりにもそれが表れるさ。", "釣り人として少し腕を上げたら、教えてあげよう。", "これで、自分だけのFish Bowlを作れるようになった。町の真ん中にキャンプを張られるのを嫌がる者が多いから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完成とは言えない。キャンプを始める前に、焚き火が一つ必要だ。たいていの料理人なら火のおこし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0xe0c1c700, 0xc4adeb37, 0x1bcf05fd, 0x7ea339f7, 0x54727538, "....." },
  [97921] = { "キャンプ101：Herbalism", "スキルの熟練を示したら、Elwynn ForestのHerbalist Pomeroyと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "どうやら薬草学の腕が少し上がったみたいだね。花摘みはただの暇つぶしじゃないんだよ。役にも立つし……儲かりもする。\n\n野営地用のIncense Candleの作り方を教えてくれる奴を知ってるよ。治療師や呪文使いを戦いに踏みとどまらせるには、士気の高さが肝心だ。Incense Candleがあれば、魔法使いたちがきっと喜ぶような後押しになるさ。", nil, "これで、自分だけのIncense Candleを作れるようになった。町の真ん中にキャンプを張られるのを嫌がる者が多いから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完成とは言えない。キャンプを始める前に、焚き火が一つ必要だ。たいていの料理人なら火のおこし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0xd7cde71c, 0xd56c7091, 0xe0048777, nil, 0x52608ebe, "...m." },
  [97922] = { "キャンプ101：Leatherworking", "スキルの熟練を示したら、GoldshireのAdele Fielderと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "革細工師になったんだってな。いいことだ、{class}。暑い日には涼しく、雨の日には濡れないテントの作り方を教えてくれる奴を知ってるよ。\n\n頭の上にいいテントがあれば、旅のあいだも頭を冴えさせておくのに必要な休息をしっかり取れるってわけさ。", "ああ、教えてあげられるよ。", "さあ、これで君だけの野営用テントだ。町の真ん中にテントを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出かける必要があるよ。\n\nああ、それと覚えておいてくれ。焚き火のない野営地は完成とは言えない。野営地を始める前に、焚き火がひとつ必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる人のところへ行って、基本を学んでおくといい。", 0x40d05936, 0xd01e7cfe, 0x86e620e9, 0xf40d0e18, 0x01530ff6, "....." },
  [97923] = { "キャンプ101：Mining", "スキルの熟練を示したら、StormwindのGelman Stonehandと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "Miningは一番華やかな仕事じゃないが、まっとうな良い仕事だし、試してみるにはいい職業だよ。\n\n野営地用のLodestoneの作り方を教えてくれる奴を知ってるよ。こいつを建てれば、剣を振るいたい連中がみんな、あんたの焚き火の周りに喜んで集まってきて、戦闘の腕を上げる「ひと押し」をたっぷり浴びていくだろうさ。", nil, "ほら、これで自分だけのLodestoneを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0xa8fe12f3, 0x996abb28, 0x8ef0fff6, nil, 0x0b8098cd, "...m." },
  [97924] = { "キャンプ101：Skinning", "スキルの熟練を示したら、GoldshireのHelene Peltskinnerと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "倒れた獣から皮をうまく剥ぎ取れるってのは、冒険者が持てる中でもかなり価値のある技なんだ。\n\n野営地用のCamp Chairの作り方を教えてくれる奴を知ってるよ。ときには腰を下ろしてひと休みするのも大事でね、集めた皮を使えば、座り心地のいい椅子が作れる。少しくつろげば、最高の調子を保てるし、次に揉め事に巻き込まれた時には、ここぞというところで一撃を加えられるってもんだ。", "少しでも腕があるなら、いくつか教えてやれるぞ。", "ほら、これで自分だけのCamp Chairを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0x14236b38, 0x7687adb0, 0x1755b1ba, 0xd511ff51, 0x98c24a76, "....." },
  [97925] = { "キャンプ101：Tailoring", "スキルの熟練を示したら、Elwynn ForestのEastvale Logging CampにいるEldrinと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "Tailoringは、打ち込むには意外なほど強力な生産スキルだ。きっとあんたの役に立つよ。\n\n腕が足りていればの話だが、野営地用のFaction Bannerの作り方を教えてくれる奴を知ってるよ。どんな戦場でも、鼓舞と士気は成功の鍵だ。心を奮い立たせる旗があれば、元気を保つのに大いに役立つさ。", nil, "さあ、これで君も自分だけのRallying Bannerを作れるようになった。町の真ん中に野営地を張られるのを好む者はあまりいないから、試してみたいなら荒野へ出かける必要があるよ。\n\nああ、それと覚えておいてくれ。焚き火のない野営地は完成とは言えない。野営地を始める前に、焚き火がひとつ必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる人のところへ行って、基本を学んでおくといい。", 0xde7f398c, 0x7350f5be, 0x49663bd1, nil, 0x8e312c30, "...m." },
  [97926] = { "間に合わせ", "Alexston's ReplyをDarkshoreのAuberdineにいるThundris Windweaverに届けてください。", "そんなに簡単に助けられればいいのだけどな、{class}。本当にそう思う。\n\n我々の土地でもっと時間を過ごすことにすれば、多くの者が困窮しているのがわかるだろう。Stormwindの金庫はかつてのようではなく、残っているものも薄く広く分けられている。\n\n次にあの長老に会ったら、この返事を渡してくれ。彼が望んでいるものではないが、今の私が差し出せるのはこれだけなのだ。", "戻ったか。Stormwindからはどんな知らせだ？", "本当に悲しい知らせです。それでも、はるばる来てくれたことに感謝します。\n\nStormwindもDarnassusも救援に来ない以上、Auberdineの運命は私たち自身で決めるしかないようです。", 0xe4477319, 0xeee57b55, 0x5de57436, 0x33442a57, 0x68b57782, "....." },
  [97927] = { "キャンプ101：Alchemy", "スキルの熟練を示したら、Thunder BluffのKrayと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "で、錬金術師として酒や薬をこしらえる道を選んだってわけか。きっと旅で役に立つだろうよ。\n\n野営地用のMana Wellの作り方を教えてくれる奴を知ってるよ。こいつを建てれば、治療師や呪文使いの連中がみんな、爽やかな一杯を味わいに駆けつけてくるさ。", nil, nil, 0x32f4ba12, 0x9fd6db54, 0xf6c52c29, nil, nil, "...mm" },
  [97928] = { "キャンプ101：Blacksmithing", "スキルの熟練を示したら、Thunder BluffのThrag Stonehoofと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "で、鍛冶屋になったんだって？ 刃を決して鈍らせたくないなら、いい選択だよ。\n\nSharpening Wheelの作り方を教えて、その手助けをしてくれる奴を知ってるよ。野営地でこいつを出せば、そのあたりのウォリアーやローグがみんな、武器を研ぎに列を作るだろうさ。", nil, nil, 0x16979ea3, 0x0c123764, 0x469a706e, nil, nil, "...mm" },
  [97929] = { "キャンプ101：Enchanting", "スキルの熟練を示したら、Thunder BluffのMot Dawnstriderと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "エンチャンターはなんでもより良くしてくれるし、荒野の野営地ならどこでも歓迎されるもんだ。\n\n野営地用のEnchanted Luteの作り方を教えてくれる奴を知ってるよ。暇な時間に楽しみを見つけるのはすごく大事なことでね、この魔法の品があれば、またほこりっぽい旅路に出た時、どんな困難にも耐えられるようにしてくれるさ。", nil, nil, 0x2e9b8c15, 0x907d3afc, 0xb4a29ffc, nil, nil, "...mm" },
  [97930] = { "キャンプ101：Engineering", "スキルの熟練を示したら、MulgoreのVenture Co. MineにいるTwizwick Sprocketgrindと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "あんたみたいなエンジニアは、面白半分にも儲けのためにも、あらゆる部品やボットや爆弾をこしらえられるんだよな。\n\n野営地用のReagent Botの作り方を教えてくれる奴を知ってるよ。この便利な自動人形が物資を切らさないようにしてくれるから、あんたも仲間も、呪文の燃料になる材料を切らすことはなくなるさ。", nil, nil, 0x1cb4025b, 0xcc961537, 0x549b28c0, nil, nil, "...mm" },
  [97931] = { "キャンプ101：First Aid", "スキルの熟練を示したら、Bloodhoof VillageのVira Younghoofと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "First Aidを始めたって？ {class}としては、立派で……しかも実用的な道だね。\n\n野営地用のFirst Aid Kitの作り方を教えてくれる奴を知ってるよ。冒険の世界じゃ怪我はつきものだし、野営地で必要な治療を施してやれば、命を救うことにだってなるかもしれない。", nil, "ほら、これで自分だけのFirst Aid Kitを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0x6e7c255b, 0x86c85202, 0x32ff3188, nil, 0x3a282524, "...m." },
  [97932] = { "キャンプ101：Fishing", "スキルの熟練を示したら、Bloodhoof VillageのUthan Stillwaterと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "そうは思わないかもしれないが、釣り人としての腕は野営地で案外役に立つんだ。\n\n野営地用のFish Bowlの作り方を教えてくれる奴を知ってるよ。こいつを置けば、あんたや仲間の冒険者たちにちょっとした楽しみを与えられる。楽しい冒険者は強い冒険者だし、きっと戦いぶりにもそれが表れるさ。", nil, "これで、自分だけのFish Bowlを作れるようになった。町の真ん中にキャンプを張られるのを嫌がる者が多いから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完成とは言えない。キャンプを始める前に、焚き火が一つ必要だ。たいていの料理人なら火のおこし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0xe0c1c700, 0x8745cbb5, 0x1bcf05fd, nil, 0x54727538, "...m." },
  [97933] = { "キャンプ101：Herbalism", "スキルの熟練を示したら、Thunder BluffのKomin Winterhoofと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "どうやら薬草学の腕が少し上がったみたいだね。花摘みはただの暇つぶしじゃないんだよ。役にも立つし……儲かりもする。\n\n野営地用のIncense Candleの作り方を教えてくれる奴を知ってるよ。治療師や呪文使いを戦いに踏みとどまらせるには、士気の高さが肝心だ。Incense Candleがあれば、魔法使いたちがきっと喜ぶような後押しになるさ。", nil, nil, 0xd7cde71c, 0x2038d080, 0xe0048777, nil, nil, "...mm" },
  [97934] = { "キャンプ101：Leatherworking", "スキルの熟練を示したら、Bloodhoof VillageのChaw Stronghideと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "革細工師になったんだってな。いいことだ、{class}。暑い日には涼しく、雨の日には濡れないテントの作り方を教えてくれる奴を知ってるよ。\n\n頭の上にいいテントがあれば、旅のあいだも頭を冴えさせておくのに必要な休息をしっかり取れるってわけさ。", nil, "ほら、これで自分だけのテントだ。町の真ん中にテントを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0x40d05936, 0xd9c41452, 0x86e620e9, nil, 0x01530ff6, "...m." },
  [97935] = { "キャンプ101：Mining", "スキルの熟練を示したら、Thunder BluffのBrek Stonehoofと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "Miningは一番華やかな仕事じゃないが、まっとうな良い仕事だし、試してみるにはいい職業だよ。\n\n野営地用のLodestoneの作り方を教えてくれる奴を知ってるよ。こいつを建てれば、剣を振るいたい連中がみんな、あんたの焚き火の周りに喜んで集まってきて、戦闘の腕を上げる「ひと押し」をたっぷり浴びていくだろうさ。", nil, nil, 0xa8fe12f3, 0xab156797, 0x8ef0fff6, nil, nil, "...mm" },
  [97936] = { "キャンプ101：Skinning", "スキルの熟練を示したら、Bloodhoof VillageのYonn Deepcutと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "倒れた獣から皮をうまく剥ぎ取れるってのは、冒険者が持てる中でもかなり価値のある技なんだ。\n\n野営地用のCamp Chairの作り方を教えてくれる奴を知ってるよ。ときには腰を下ろしてひと休みするのも大事でね、集めた皮を使えば、座り心地のいい椅子が作れる。少しくつろげば、最高の調子を保てるし、次に揉め事に巻き込まれた時には、ここぞというところで一撃を加えられるってもんだ。", nil, "ほら、これで自分だけのCamp Chairを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0x14236b38, 0xa1684cc3, 0x1755b1ba, nil, 0x98c24a76, "...m." },
  [97937] = { "キャンプ101：Tailoring", "スキルの熟練を示したら、Thunder BluffのVhanと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "Tailoringは、打ち込むには意外なほど強力な生産スキルだ。きっとあんたの役に立つよ。\n\n腕が足りていればの話だが、野営地用のFaction Bannerの作り方を教えてくれる奴を知ってるよ。どんな戦場でも、鼓舞と士気は成功の鍵だ。心を奮い立たせる旗があれば、元気を保つのに大いに役立つさ。", nil, nil, 0xde7f398c, 0x21c61245, 0x49663bd1, nil, nil, "...mm" },
  [97938] = { "キャンプ101：Alchemy", "スキルの熟練を示したら、DolanaarのCyndra Kindwhisperと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "で、錬金術師として酒や薬をこしらえる道を選んだってわけか。きっと旅で役に立つだろうよ。\n\n野営地用のMana Wellの作り方を教えてくれる奴を知ってるよ。こいつを建てれば、治療師や呪文使いの連中がみんな、爽やかな一杯を味わいに駆けつけてくるさ。", nil, "ほら、これで自分だけのMana Wellを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0x32f4ba12, 0x4f3974b2, 0xf6c52c29, nil, 0xbd7a9e72, "...m." },
  [97939] = { "キャンプ101：Blacksmithing", "スキルの熟練を示したら、DarkshoreのAuberdineにいるElisa Steelhandと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "で、鍛冶屋になったんだって？ 刃を決して鈍らせたくないなら、いい選択だよ。\n\nSharpening Wheelの作り方を教えて、その手助けをしてくれる奴を知ってるよ。野営地でこいつを出せば、そのあたりのウォリアーやローグがみんな、武器を研ぎに列を作るだろうさ。", nil, nil, 0x16979ea3, 0xc4d92ccf, 0x469a706e, nil, nil, "...mm" },
  [97940] = { "キャンプ101：Enchanting", "スキルの熟練を示したら、TeldrassilのOracle GladeにいるAlanna Raveneyeと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "エンチャンターはなんでもより良くしてくれるし、荒野の野営地ならどこでも歓迎されるもんだ。\n\n野営地用のEnchanted Luteの作り方を教えてくれる奴を知ってるよ。暇な時間に楽しみを見つけるのはすごく大事なことでね、この魔法の品があれば、またほこりっぽい旅路に出た時、どんな困難にも耐えられるようにしてくれるさ。", nil, nil, 0x2e9b8c15, 0x491f3400, 0xb4a29ffc, nil, nil, "...mm" },
  [97941] = { "キャンプ101：Engineering", "スキルの熟練を示したら、DarkshoreのAuberdineにいるJenna Lemkenilliと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "あんたみたいなエンジニアは、面白半分にも儲けのためにも、あらゆる部品やボットや爆弾をこしらえられるんだよな。\n\n野営地用のReagent Botの作り方を教えてくれる奴を知ってるよ。この便利な自動人形が物資を切らさないようにしてくれるから、あんたも仲間も、呪文の燃料になる材料を切らすことはなくなるさ。", nil, nil, 0x1cb4025b, 0xf8ad00a9, 0x549b28c0, nil, nil, "...mm" },
  [97942] = { "キャンプ101：First Aid", "スキルの熟練を示したら、DolanaarのByancieと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "First Aidを始めたって？ {class}としては、立派で……しかも実用的な道だね。\n\n野営地用のFirst Aid Kitの作り方を教えてくれる奴を知ってるよ。冒険の世界じゃ怪我はつきものだし、野営地で必要な治療を施してやれば、命を救うことにだってなるかもしれない。", nil, "ほら、これで自分だけのFirst Aid Kitを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0x6e7c255b, 0xae626583, 0x32ff3188, nil, 0x3a282524, "...m." },
  [97943] = { "キャンプ101：Fishing", "スキルの熟練を示したら、DarnassusのAstaiaと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "そうは思わないかもしれないが、釣り人としての腕は野営地で案外役に立つんだ。\n\n野営地用のFish Bowlの作り方を教えてくれる奴を知ってるよ。こいつを置けば、あんたや仲間の冒険者たちにちょっとした楽しみを与えられる。楽しい冒険者は強い冒険者だし、きっと戦いぶりにもそれが表れるさ。", nil, nil, 0xe0c1c700, 0x430360e0, 0x1bcf05fd, nil, nil, "...mm" },
  [97944] = { "キャンプ101：Herbalism", "スキルの熟練を示したら、DolanaarのMalorne Bladeleafと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "どうやら薬草学の腕が少し上がったみたいだね。花摘みはただの暇つぶしじゃないんだよ。役にも立つし……儲かりもする。\n\n野営地用のIncense Candleの作り方を教えてくれる奴を知ってるよ。治療師や呪文使いを戦いに踏みとどまらせるには、士気の高さが肝心だ。Incense Candleがあれば、魔法使いたちがきっと喜ぶような後押しになるさ。", nil, "これで、自分だけのIncense Candleを作れるようになった。町の真ん中にキャンプを張られるのを嫌がる者が多いから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完成とは言えない。キャンプを始める前に、焚き火が一つ必要だ。たいていの料理人なら火のおこし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0xd7cde71c, 0x43147a9b, 0xe0048777, nil, 0x52608ebe, "...m." },
  [97946] = { "キャンプ101：Leatherworking", "スキルの熟練を示したら、DolanaarからDarnassusへ向かう道沿いにいるNadyia Maneweaverと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "革細工師になったんだってな。いいことだ、{class}。暑い日には涼しく、雨の日には濡れないテントの作り方を教えてくれる奴を知ってるよ。\n\n頭の上にいいテントがあれば、旅のあいだも頭を冴えさせておくのに必要な休息をしっかり取れるってわけさ。", nil, nil, 0x40d05936, 0xb201c757, 0x86e620e9, nil, nil, "...mm" },
  [97948] = { "キャンプ101：Mining", "スキルの熟練を示したら、AuberdineのKurdram Stonehammerと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "Miningは一番華やかな仕事じゃないが、まっとうな良い仕事だし、試してみるにはいい職業だよ。\n\n野営地用のLodestoneの作り方を教えてくれる奴を知ってるよ。こいつを建てれば、剣を振るいたい連中がみんな、あんたの焚き火の周りに喜んで集まってきて、戦闘の腕を上げる「ひと押し」をたっぷり浴びていくだろうさ。", nil, nil, 0xa8fe12f3, 0xfa2509cd, 0x8ef0fff6, nil, nil, "...mm" },
  [97949] = { "キャンプ101：Skinning", "スキルの熟練を示したら、DolanaarからDarnassusへ向かう道沿いにいるRadnaal Maneweaverと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "倒れた獣から皮をうまく剥ぎ取れるってのは、冒険者が持てる中でもかなり価値のある技なんだ。\n\n野営地用のCamp Chairの作り方を教えてくれる奴を知ってるよ。ときには腰を下ろしてひと休みするのも大事でね、集めた皮を使えば、座り心地のいい椅子が作れる。少しくつろげば、最高の調子を保てるし、次に揉め事に巻き込まれた時には、ここぞというところで一撃を加えられるってもんだ。", nil, "ほら、これで自分だけのCamp Chairを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0x14236b38, 0xf8d27207, 0x1755b1ba, nil, 0x98c24a76, "...m." },
  [97950] = { "キャンプ101：Tailoring", "スキルの熟練を示したら、DarnassusのTriannaと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "Tailoringは、打ち込むには意外なほど強力な生産スキルだ。きっとあんたの役に立つよ。\n\n腕が足りていればの話だが、野営地用のFaction Bannerの作り方を教えてくれる奴を知ってるよ。どんな戦場でも、鼓舞と士気は成功の鍵だ。心を奮い立たせる旗があれば、元気を保つのに大いに役立つさ。", nil, nil, 0xde7f398c, 0x8c6f7b63, 0x49663bd1, nil, nil, "...mm" },
  [97951] = { "キャンプ101：Alchemy", "スキルの熟練を示したら、BrillのCarolai Aniseと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "で、錬金術師として酒や薬をこしらえる道を選んだってわけか。きっと旅で役に立つだろうよ。\n\n野営地用のMana Wellの作り方を教えてくれる奴を知ってるよ。こいつを建てれば、治療師や呪文使いの連中がみんな、爽やかな一杯を味わいに駆けつけてくるさ。", nil, "ほら、これで自分だけのMana Wellを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0x32f4ba12, 0x988c4de3, 0xf6c52c29, nil, 0xbd7a9e72, "...m." },
  [97952] = { "キャンプ101：Blacksmithing", "スキルの熟練を示したら、UndercityのBasil Fryeと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "で、鍛冶屋になったんだって？ 刃を決して鈍らせたくないなら、いい選択だよ。\n\nSharpening Wheelの作り方を教えて、その手助けをしてくれる奴を知ってるよ。野営地でこいつを出せば、そのあたりのウォリアーやローグがみんな、武器を研ぎに列を作るだろうさ。", "ああ、教えてあげられるよ。", nil, 0x16979ea3, 0xca12e161, 0x469a706e, 0xf40d0e18, nil, "....m" },
  [97953] = { "キャンプ101：Enchanting", "スキルの熟練を示したら、BrillのVance Undergloomと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "エンチャンターはなんでもより良くしてくれるし、荒野の野営地ならどこでも歓迎されるもんだ。\n\n野営地用のEnchanted Luteの作り方を教えてくれる奴を知ってるよ。暇な時間に楽しみを見つけるのはすごく大事なことでね、この魔法の品があれば、またほこりっぽい旅路に出た時、どんな困難にも耐えられるようにしてくれるさ。", nil, nil, 0x2e9b8c15, 0x24bb4093, 0xb4a29ffc, nil, nil, "...mm" },
  [97954] = { "キャンプ101：Engineering", "スキルの熟練を示したら、UndercityのGraham Van Talenと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "あんたみたいなエンジニアは、面白半分にも儲けのためにも、あらゆる部品やボットや爆弾をこしらえられるんだよな。\n\n野営地用のReagent Botの作り方を教えてくれる奴を知ってるよ。この便利な自動人形が物資を切らさないようにしてくれるから、あんたも仲間も、呪文の燃料になる材料を切らすことはなくなるさ。", nil, nil, 0x1cb4025b, 0xa25e841e, 0x549b28c0, nil, nil, "...mm" },
  [97955] = { "キャンプ101：First Aid", "スキルの熟練を示したら、BrillのNurse Neelaと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "First Aidを始めたって？ {class}としては、立派で……しかも実用的な道だね。\n\n野営地用のFirst Aid Kitの作り方を教えてくれる奴を知ってるよ。冒険の世界じゃ怪我はつきものだし、野営地で必要な治療を施してやれば、命を救うことにだってなるかもしれない。", nil, "ほら、これで自分だけのFirst Aid Kitを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0x6e7c255b, 0x85dce6c2, 0x32ff3188, nil, 0x3a282524, "...m." },
  [97956] = { "キャンプ101：Fishing", "スキルの熟練を示したら、BrillのClyde Kellenと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "そうは思わないかもしれないが、釣り人としての腕は野営地で案外役に立つんだ。\n\n野営地用のFish Bowlの作り方を教えてくれる奴を知ってるよ。こいつを置けば、あんたや仲間の冒険者たちにちょっとした楽しみを与えられる。楽しい冒険者は強い冒険者だし、きっと戦いぶりにもそれが表れるさ。", nil, nil, 0xe0c1c700, 0x3f726cba, 0x1bcf05fd, nil, nil, "...mm" },
  [97957] = { "キャンプ101：Herbalism", "スキルの熟練を示したら、BrillのFaruzaと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "どうやら薬草学の腕が少し上がったみたいだね。花摘みはただの暇つぶしじゃないんだよ。役にも立つし……儲かりもする。\n\n野営地用のIncense Candleの作り方を教えてくれる奴を知ってるよ。治療師や呪文使いを戦いに踏みとどまらせるには、士気の高さが肝心だ。Incense Candleがあれば、魔法使いたちがきっと喜ぶような後押しになるさ。", nil, "これで、自分だけのIncense Candleを作れるようになった。町の真ん中にキャンプを張られるのを嫌がる者が多いから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完成とは言えない。キャンプを始める前に、焚き火が一つ必要だ。たいていの料理人なら火のおこし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0xd7cde71c, 0xb117ea06, 0xe0048777, nil, 0x52608ebe, "...m." },
  [97958] = { "キャンプ101：Leatherworking", "スキルの熟練を示したら、BrillからUndercityへ向かう道沿いにいるShelene Rhobartと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "革細工師になったんだってな。いいことだ、{class}。暑い日には涼しく、雨の日には濡れないテントの作り方を教えてくれる奴を知ってるよ。\n\n頭の上にいいテントがあれば、旅のあいだも頭を冴えさせておくのに必要な休息をしっかり取れるってわけさ。", nil, nil, 0x40d05936, 0x90536b6c, 0x86e620e9, nil, nil, "...mm" },
  [97959] = { "キャンプ101：Mining", "スキルの熟練を示したら、UndercityのBrom Killianと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "Miningは一番華やかな仕事じゃないが、まっとうな良い仕事だし、試してみるにはいい職業だよ。\n\n野営地用のLodestoneの作り方を教えてくれる奴を知ってるよ。こいつを建てれば、剣を振るいたい連中がみんな、あんたの焚き火の周りに喜んで集まってきて、戦闘の腕を上げる「ひと押し」をたっぷり浴びていくだろうさ。", nil, "ほら、これで自分だけのLodestoneを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0xa8fe12f3, 0x352725d8, 0x8ef0fff6, nil, 0x0b8098cd, "...m." },
  [97960] = { "キャンプ101：Skinning", "スキルの熟練を示したら、BrillからUndercityへ向かう道沿いにいるRand Rhobartと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "倒れた獣から皮をうまく剥ぎ取れるってのは、冒険者が持てる中でもかなり価値のある技なんだ。\n\n野営地用のCamp Chairの作り方を教えてくれる奴を知ってるよ。ときには腰を下ろしてひと休みするのも大事でね、集めた皮を使えば、座り心地のいい椅子が作れる。少しくつろげば、最高の調子を保てるし、次に揉め事に巻き込まれた時には、ここぞというところで一撃を加えられるってもんだ。", nil, "さあ、これで自分だけのCamp Chairが作れるようになったよ。たいていの人は町の真ん中でキャンプを張られるのをあまり好まないから、試してみたいなら荒野へ出かける必要があるね。\n\nああ、それと覚えておいてくれ。焚き火がなければ、キャンプは完成しない。キャンプを始める前に、焚き火を一つ用意する必要がある。たいていの料理人なら火の起こし方を教えてくれるよ。まだなら、料理の技術を教えてくれる人を訪ねて、基本を学んでおくといいだろう。", 0x14236b38, 0xab414e66, 0x1755b1ba, nil, 0x98c24a76, "...m." },
  [97961] = { "キャンプ101：Tailoring", "スキルの熟練を示したら、DeathknellからBrillへ向かう道沿いにいるBowen Brisboiseと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "Tailoringは、打ち込むには意外なほど強力な生産スキルだ。きっとあんたの役に立つよ。\n\n腕が足りていればの話だが、野営地用のFaction Bannerの作り方を教えてくれる奴を知ってるよ。どんな戦場でも、鼓舞と士気は成功の鍵だ。心を奮い立たせる旗があれば、元気を保つのに大いに役立つさ。", nil, nil, 0xde7f398c, 0xe62978ca, 0x49663bd1, nil, nil, "...mm" },
  [97963] = { "キャンプ101：Alchemy", "スキルの熟練を示したら、Shen'dar VillageのNyassa Swiftdraughtと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "で、錬金術師として酒や薬をこしらえる道を選んだってわけか。きっと旅で役に立つだろうよ。\n\n野営地用のMana Wellの作り方を教えてくれる奴を知ってるよ。こいつを建てれば、治療師や呪文使いの連中がみんな、爽やかな一杯を味わいに駆けつけてくるさ。", nil, "ほら、これで自分だけのMana Wellを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0x32f4ba12, 0x13d46d67, 0xf6c52c29, nil, 0xbd7a9e72, "...m." },
  [97964] = { "キャンプ101：Blacksmithing", "スキルの熟練を示したら、Shen'dar VillageのAedi Thriceforgedと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "で、鍛冶屋になったんだって？ 刃を決して鈍らせたくないなら、いい選択だよ。\n\nSharpening Wheelの作り方を教えて、その手助けをしてくれる奴を知ってるよ。野営地でこいつを出せば、そのあたりのウォリアーやローグがみんな、武器を研ぎに列を作るだろうさ。", "素質があるなら、教えてあげよう。", "これでよし、これで君も自分だけのSharpening Wheelを作れるようになった。町の真ん中にキャンプを張られるのを喜ぶ者はあまりいないから、試してみたいなら野外へ出るといい。\n\nああ、それから覚えておいてくれ、焚き火のないキャンプなんてキャンプとは言えない。キャンプを始める前に、焚き火が一つ必要になる。たいていの料理人なら、火の起こし方を教えてくれるはずだ。まだなら、料理の技を教えてくれる人のところへ行って、基本を学んでおくといいだろう。", 0x16979ea3, 0x2e5ffa5c, 0x469a706e, 0xfee6b233, 0xe5c38af5, "....." },
  [97965] = { "キャンプ101：First Aid", "スキルの熟練を示したら、Shen'dar VillageのNaleeia Tattermendと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "First Aidを始めたって？ {class}としては、立派で……しかも実用的な道だね。\n\n野営地用のFirst Aid Kitの作り方を教えてくれる奴を知ってるよ。冒険の世界じゃ怪我はつきものだし、野営地で必要な治療を施してやれば、命を救うことにだってなるかもしれない。", nil, "ほら、これで自分だけのFirst Aid Kitを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0x6e7c255b, 0x022a7953, 0x32ff3188, nil, 0x3a282524, "...m." },
  [97967] = { "キャンプ101：Fishing", "スキルの熟練を示したら、Shen'dar VillageのFenn Fairweatherと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "そうは思わないかもしれないが、釣り人としての腕は野営地で案外役に立つんだ。\n\n野営地用のFish Bowlの作り方を教えてくれる奴を知ってるよ。こいつを置けば、あんたや仲間の冒険者たちにちょっとした楽しみを与えられる。楽しい冒険者は強い冒険者だし、きっと戦いぶりにもそれが表れるさ。", nil, "これで、自分だけのFish Bowlを作れるようになった。町の真ん中にキャンプを張られるのを嫌がる者が多いから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完成とは言えない。キャンプを始める前に、焚き火が一つ必要だ。たいていの料理人なら火のおこし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0xe0c1c700, 0x62e07843, 0x1bcf05fd, nil, 0x54727538, "...m." },
  [97968] = { "キャンプ101：Herbalism", "スキルの熟練を示したら、ValanaarのSyriel Nightrainと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "どうやら薬草学の腕が少し上がったみたいだね。花摘みはただの暇つぶしじゃないんだよ。役にも立つし……儲かりもする。\n\n野営地用のIncense Candleの作り方を教えてくれる奴を知ってるよ。治療師や呪文使いを戦いに踏みとどまらせるには、士気の高さが肝心だ。Incense Candleがあれば、魔法使いたちがきっと喜ぶような後押しになるさ。", nil, "これで、自分だけのIncense Candleを作れるようになった。町の真ん中にキャンプを張られるのを嫌がる者が多いから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完成とは言えない。キャンプを始める前に、焚き火が一つ必要だ。たいていの料理人なら火のおこし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0xd7cde71c, 0xb11f2169, 0xe0048777, nil, 0x52608ebe, "...m." },
  [97969] = { "キャンプ101：Leatherworking", "スキルの熟練を示したら、Shen'dar VillageのIndari Sunseamと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "革細工師になったんだってな。いいことだ、{class}。暑い日には涼しく、雨の日には濡れないテントの作り方を教えてくれる奴を知ってるよ。\n\n頭の上にいいテントがあれば、旅のあいだも頭を冴えさせておくのに必要な休息をしっかり取れるってわけさ。", nil, "ほら、これで自分だけのテントだ。町の真ん中にテントを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0x40d05936, 0x02561574, 0x86e620e9, nil, 0x01530ff6, "...m." },
  [97970] = { "キャンプ101：Mining", "スキルの熟練を示したら、Shen'dar VillageのMessana Crestwindと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "Miningは一番華やかな仕事じゃないが、まっとうな良い仕事だし、試してみるにはいい職業だよ。\n\n野営地用のLodestoneの作り方を教えてくれる奴を知ってるよ。こいつを建てれば、剣を振るいたい連中がみんな、あんたの焚き火の周りに喜んで集まってきて、戦闘の腕を上げる「ひと押し」をたっぷり浴びていくだろうさ。", "素質があるなら、訓練してあげよう。", "ほら、これで自分だけのLodestoneを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0xa8fe12f3, 0x797ded19, 0x8ef0fff6, 0xfebb9665, 0x0b8098cd, "....." },
  [97971] = { "キャンプ101：Skinning", "スキルの熟練を示したら、Shen'dar VillageのMendalass Tattermendと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "倒れた獣から皮をうまく剥ぎ取れるってのは、冒険者が持てる中でもかなり価値のある技なんだ。\n\n野営地用のCamp Chairの作り方を教えてくれる奴を知ってるよ。ときには腰を下ろしてひと休みするのも大事でね、集めた皮を使えば、座り心地のいい椅子が作れる。少しくつろげば、最高の調子を保てるし、次に揉め事に巻き込まれた時には、ここぞというところで一撃を加えられるってもんだ。", nil, "ほら、これで自分だけのCamp Chairを作れるようになった。町の真ん中にキャンプを張られるのを好む者はあまりいないから、試してみたいなら荒野へ出る必要がある。\n\nああ、それと覚えておいてくれ。焚き火のないキャンプは完全とは言えない。キャンプを始める前に焚き火が必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる者のところへ行って、基本を学んでおくといい。", 0x14236b38, 0xb45769bd, 0x1755b1ba, nil, 0x98c24a76, "...m." },
  [97972] = { "キャンプ101：Tailoring", "スキルの熟練を示したら、Shen'dar VillageのTaleen Shimmerthreadと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "Tailoringは、打ち込むには意外なほど強力な生産スキルだ。きっとあんたの役に立つよ。\n\n腕が足りていればの話だが、野営地用のFaction Bannerの作り方を教えてくれる奴を知ってるよ。どんな戦場でも、鼓舞と士気は成功の鍵だ。心を奮い立たせる旗があれば、元気を保つのに大いに役立つさ。", nil, nil, 0xde7f398c, 0x496099ef, 0x49663bd1, nil, nil, "...mm" },
  [97973] = { "キャンプ101：Tailoring", "スキルの熟練を示したら、Shen'dar VillageのTaleen Shimmerthreadと話して、あなたの職業用のキャンプ用品の作り方を教わってください。", "Tailoringは、打ち込むには意外なほど強力な生産スキルだ。きっとあんたの役に立つよ。\n\n腕が足りていればの話だが、野営地用のFaction Bannerの作り方を教えてくれる奴を知ってるよ。どんな戦場でも、鼓舞と士気は成功の鍵だ。心を奮い立たせる旗があれば、元気を保つのに大いに役立つさ。", "専門技能の腕を少し上げたら、また話しに来てくれ。", "さあ、これで君も自分だけのRallying Bannerを作れるようになった。町の真ん中に野営地を張られるのを好む者はあまりいないから、試してみたいなら荒野へ出かける必要があるよ。\n\nああ、それと覚えておいてくれ。焚き火のない野営地は完成とは言えない。野営地を始める前に、焚き火がひとつ必要だ。たいていの料理人なら火の起こし方を教えてくれる。まだなら、料理の技術を教えてくれる人のところへ行って、基本を学んでおくといい。", 0xde7f398c, 0x496099ef, 0x49663bd1, 0x6c0def5f, 0x8e312c30, "....." },
  [97977] = { "自然の呼び声", "Gnarlpine Totemを$N1個集め、Tarindrellaのところへ持って行ってください。", "Gnarlpineのfurbolgが、古くからの盟友にそう簡単に背を向けるはずがありません。彼らの窮状をもっと知らなければなりません。\n\n彼らの捨てられた住処でトーテムを探してください。去る時の混乱を生き延びたものがあれば、その彫り物から、ここで何が起きたのかがもっとわかるかもしれません。\n\n彼らの野営地は谷の西の端沿いにありますが、grellやgrellkinがそれをさらに遠くへ散らしてしまっているかもしれません。", "もっと大きなトーテムを見つけても気にしなくていい。仮に持ってこられたとしても、私にはどうしようもないからな！", "ああ、思っていたよりもさらにひどい。\n\nこの彫刻によると、Gnarlpineは何か大きな影に滅ぼされる悪夢を見るようになったそうです。やがてその恐怖は怒りに変わり、影はかつてのエルフの友へと姿を変えました。自分の心が離れていくのを自覚するなんて……\n\nこれがTeldrassilで起きていることをより深く理解する助けになることを願うばかりです。助けてくれてありがとう、{name}。", 0x8ddb1b2f, 0x0263ede4, 0x02e09ddc, 0xc1ecd12f, 0x12ba2b7d, "....." },
  [97979] = { "女神の恵み", "Elune's LightとShadowmeldを使ってください。", "あなたは星の子、kaldoreiとして生まれ、この世界の他の何にも似ていない生得の権利を受け継いでいます。Eluneの恩寵は私たちの強さを照らし、一撃を確かに命中させてくれるかもしれません。あるいは、月が太陽を覆い隠すように、私たちの姿を隠す助けとなるかもしれません。\n\nMount Hyjalの防衛の後の私たちのLong Vigilは終わり、私たちは他の者たちとのAllianceに加わりました。その者たちとはいずれ会うことになるでしょう。今のところ、あなたはTeldrassilの枝に抱かれています。\n\nMother Moonの賜物を示し、その祝福を浴びなさい。", "Mother Moonの光を浴びることほど大きな喜びは、そうありません。", "我らが女神のもたらすものを、あなたは目にしました。それを賢く使いなさい。そうすれば、女神があなたを見捨てることは決してありません。", 0x1c2fae6f, 0x2d344d16, 0x2061ad94, 0x47c42a76, 0xc6da7ff1, "....." },
  [97985] = { "轟く心臓", "Thousand NeedlesでStormheartを倒し、その心臓を手に入れて下さい。", "実に興味深いでしょう？ abominationの創造の秘密に触れるのは、これが初めてなのです。\n\nこの覚え書きを研究していたのですが、どうやら心臓が必要なようです。巨大な心臓が！\n\n聞くところによると、Thousand Needlesの峡谷の縁をうろついている、Stormheartという見事な大きさのthunder lizardがいるそうです。そんな名前なら、きっと完璧な心臓を持っているに違いありません。その心臓が絶対に欲しいのです！\n\nああ、それと、仲間を連れて行くことをお勧めします。Stormheartはおとなしいことで知られてはいませんから。", nil, nil, 0xf631fcf2, 0xc353cffe, 0x745e4a8c, nil, nil, "...mm" },
  [97986] = { "Argent Arbiter", "Eastern PlaguelandsのBlackwood Lakeの北西にある、もう一つのArgent Dawnの野営地で衛生兵と話す。", "我々のargentの斥候の一人、Hailenは、郊外と高地の担当だ。彼女はたいてい二週間ごとに野営地へ戻ってくる。\n\n君の話からすると、君が見つけたのは彼女の亡骸だったかもしれない。だが、君が川岸で見たような他のskyborneは、我々は見ていない。\n\nBlackwood Lakeの北西にも、もう一つ野営地がある。そこの衛生兵も、この件について何か知っているかもしれない。前線にはまだ見るべきものがたくさんある。", nil, nil, 0xbdc47275, 0x5d73b8eb, 0x89fac15d, nil, nil, "...mm" },
  [97987] = { "Stormwindの高位騎士団", "StormwindのThe ParkにいるSaera Wirrawayと話す。", "この崖が崩れた頃、エルフのバリスタが撃たれる音を聞いた。矢がQuel'Thalasへ続く道沿いの我が家のすぐ近くに、危ういほど突き刺さった。\n\n私は木々と瓦礫の雪崩を後にして逃げた。shen'doreiとしか思えない言葉で叫ぶ声が聞こえた！私の耳にさえ耳障りだった。聞き取れたのはわずかな言葉だけだ。「裏切り者」「血」「敵」。\n\n私の提案はこうだ。この知らせを、StormwindのParkにいる高位のskyborne、Saera Wirrawayのもとへ持っていくといい。同じ血筋ではないが、かつて我々は答えを求める心を分かち合っていた。", nil, nil, 0x033fc312, 0xd5b49581, 0xe6f6841d, nil, nil, "...mm" },
  [97988] = { "Orgrimmarの風使いたち", "OrgrimmarのValley of WisdomにいるCorswyn Aserilと話す。", "この崖が崩れた頃、エルフのバリスタが撃たれる音を聞いた。矢がQuel'Thalasへ続く道沿いの我が家のすぐ近くに、危ういほど突き刺さった。\n\n私は木々と瓦礫の雪崩を後にして逃げた。shen'doreiとしか思えない言葉で叫ぶ声が聞こえた！私の耳にさえ耳障りだった。聞き取れたのはわずかな言葉だけだ。「裏切り者」「血」「敵」。\n\nこの知らせを、OrgrimmarのValley of Wisdomにいる風の形作り手のskyborne、Corswyn Aserilのもとへ持っていくといい。同じ血筋ではないが、かつて我々の心は同じ真実を求めていた。", nil, nil, 0x230fde86, 0xef93f8c9, 0x4f74ca93, nil, nil, "...mm" },
})
